import streamlit as stimport pandas as pdimport numpy as npimport plotly.express as pximport plotly.graph_objects as goimport requestsimport hashlibimport ioimport osimport qrcodeimport base64import openpyxlfrom openpyxl.styles import Font, Alignment, PatternFillfrom PIL import Imagefrom bs4 import BeautifulSoupimport pytzfrom openpyxl.utils import get_column_letterfrom openpyxl.styles import Border, Sideimport psycopg2from sqlalchemy import create_engine, textfrom datetime import datetimefrom dotenv import load_dotenvfrom passlib.context import CryptContextfrom pydantic import BaseModelfrom typing import Optionalimport cv2from openpyxl.drawing.image import Image as OpenpyxlImagefrom locales import TRANSLATIONS# Configuration unique de la page Streamlitst.set_page_config(    page_title="SACCO Connect Burundi",    page_icon="🇧🇮",    layout="wide")lang_choice = st.sidebar.selectbox("Langue / Ururimi", ["Français", "Kirundi"])current_lang = 'KI' if lang_choice == "Kirundi" else 'FR'# Raccourci pour traduire facilementt = TRANSLATIONS[current_lang]# ==========================================# 1. INITIALISATION GLOBALE DE LA SESSION# ==========================================if 'user' not in st.session_state:    st.session_state.user = Noneif 'logged_in' not in st.session_state:    st.session_state.logged_in = Falseif 'user_data' not in st.session_state:    st.session_state.user_data = None# ==========================================# 2. CONFIGURATION DE LA BASE DE DONNÉES# ==========================================load_dotenv()pwd_context = CryptContext(schemes=["bcrypt"], deprecated="auto")@st.cache_resourcedef get_db_connection():    database_url = os.getenv("DATABASE_URL")    if database_url:        if database_url.startswith("postgres://"):            database_url = database_url.replace("postgres://", "postgresql://", 1)        conn = psycopg2.connect(database_url)        engine = create_engine(            database_url,            pool_pre_ping=True,            pool_recycle=3600,            connect_args={                "keepalives": 1,                "keepalives_idle": 30,                "keepalives_interval": 10,                "keepalives_count": 5,                "connect_timeout": 10            }        )    else:        DB_CONFIG = {            "dbname": os.getenv("DB_NAME", "sacco_fintech_master"),            "user": os.getenv("DB_USER", "Sacco"),            "password": os.getenv("DB_PASSWORD", "sacco2026"),            "host": os.getenv("DB_HOST", "127.0.0.1"),            "port": os.getenv("DB_PORT", "5432")        }        conn = psycopg2.connect(**DB_CONFIG)        url = f"postgresql://{DB_CONFIG['user']}:{DB_CONFIG['password']}@{DB_CONFIG['host']}:{DB_CONFIG['port']}/{DB_CONFIG['dbname']}"        engine = create_engine(            url,            pool_pre_ping=True,            pool_recycle=3600,            connect_args={                "keepalives": 1,                "keepalives_idle": 30,                "keepalives_interval": 10,                "keepalives_count": 5,                "connect_timeout": 10            }        )    return conn, enginedb_conn, engine = get_db_connection()st.markdown("""    <style>        .stApp {            background-image: url("https://upload.wikimedia.org/wikipedia/commons/b/bf/Flag_of_Burundi.svg");             background-repeat: no-repeat;            background-attachment: fixed;            background-position: center;            background-size: 40%;            opacity: 0.98;        }        .main { background-color: rgba(255, 255, 255, 0.95); border-radius: 15px; padding: 30px; box-shadow: 0 4px 15px rgba(0,0,0,0.1); }        [data-testid="stSidebar"] { background-color: #f8f9fa; border-right: 1px solid #eee; }        .stMetric { background: white; padding: 15px; border-radius: 10px; border: 1px solid #eee; }        div[data-testid="stBaseButton-secondary"] button, div[data-testid="stBaseButton-primary"] button { background-color: #1A529B !important; color: white !important; border-color: #1A529B !important; }        div[data-testid="stBaseButton-secondary"] button:hover, div[data-testid="stBaseButton-primary"] button:hover { background-color: #143E75 !important; border-color: #143E75 !important; color: white !important; }    </style>    """, unsafe_allow_html=True)class LoginRequest(BaseModel):    telephone: str    pin: strclass InscriptionPayload(BaseModel):    telephone: str    colline: Optional[str] = None    quartier: Optional[str] = None    avenue: Optional[str] = None    maison: Optional[str] = None    nom: Optional[str] = "Non renseigné"    prenom: Optional[str] = "Membre"    age: Optional[int] = 0    sexe: Optional[str] = "M"    cni: Optional[str] = "0000"def init_db():    pin_1234_hash = hashlib.sha256("1234".encode()).hexdigest()    admin_pwd_hash = hashlib.sha256("SACCO_Bujumbura-BBIN".encode()).hexdigest()    with engine.begin() as conn:        conn.execute(text('''            CREATE TABLE IF NOT EXISTS groupes (                id SERIAL PRIMARY KEY,                 nom_groupe TEXT,                 president_id INTEGER,                 secretaire_id INTEGER,                 montant_hebdo REAL DEFAULT 5000,                 date_reunion_derniere TEXT,                 date_reunion_prochaine TEXT,                 taux_amende REAL DEFAULT 1000            )        '''))        conn.execute(text('''            CREATE TABLE IF NOT EXISTS membres (                id SERIAL PRIMARY KEY,                 nom TEXT,                 prenom TEXT,                 age INTEGER,                 sexe TEXT,                 telephone TEXT UNIQUE,                 cni TEXT,                 colline TEXT,                 quartier TEXT,                 avenue TEXT,                 maison TEXT,                 pin TEXT,                 role TEXT,                 groupe_id INTEGER,                 doit_changer_pin INTEGER DEFAULT 0,                 solde_epargne REAL DEFAULT 0,                 solde_pret REAL DEFAULT 0,                 is_active INTEGER DEFAULT 1,                 caisse_sociale REAL DEFAULT 0,                 last_login TEXT,                 status_presence TEXT DEFAULT 'A',                credit_en_cours REAL DEFAULT 0,                 credit_rembourse REAL DEFAULT 0,                 credit_restant REAL DEFAULT 0,                solde_pret_social REAL DEFAULT 0            )        '''))        conn.execute(text('''            CREATE TABLE IF NOT EXISTS demandes_sociales (                id SERIAL PRIMARY KEY,                 membre_id INTEGER,                 montant_demande REAL,                 motif TEXT,                 status TEXT DEFAULT 'En attente',                 date_demande TEXT            )        '''))        conn.execute(text('''            CREATE TABLE IF NOT EXISTS logs (                id SERIAL PRIMARY KEY,                 utilisateur TEXT,                 action TEXT,                 details TEXT,                 date TEXT            )        '''))        conn.execute(text('''            CREATE TABLE IF NOT EXISTS prets (                id SERIAL PRIMARY KEY,                 membre_id INTEGER,                 montant REAL,                 motif TEXT,                 reste_a_payer REAL,                 status TEXT,                 date_demande TEXT,                 autorise_par TEXT,                 date_validation TEXT            )        '''))        res_groupe = conn.execute(text("SELECT COUNT(*) FROM groupes")).fetchone()[0]        if res_groupe == 0:            conn.execute(text("INSERT INTO groupes (nom_groupe, montant_hebdo) VALUES ('Groupe Alpha', 5000)"))        users = [            {                "telephone": "admin", "pin": admin_pwd_hash, "nom": "Administrateur", "prenom": "Système",                "age": 35, "sexe": "M", "cni": "99999", "colline": "Bujumbura", "quartier": "Central",                "avenue": "Avenue Admin", "maison": "1", "role": "admin", "groupe_id": None            },            {                "telephone": "1111", "pin": pin_1234_hash, "nom": "Président", "prenom": "Groupe",                "age": 45, "sexe": "M", "cni": "22222", "colline": "Bujumbura", "quartier": "Nord",                "avenue": "Avenue 2", "maison": "34", "role": "president", "groupe_id": 1            },            {                "telephone": "2222", "pin": pin_1234_hash, "nom": "Secrétaire", "prenom": "Groupe",                "age": 30, "sexe": "M", "cni": "11111", "colline": "Bujumbura", "quartier": "Centrum",                "avenue": "Avenue 1", "maison": "12", "role": "secretaire", "groupe_id": 1            },            {                "telephone": "0000", "pin": pin_1234_hash, "nom": "NKURUNZIZA", "prenom": "Raphael",                "age": 28, "sexe": "M", "cni": "00000", "colline": "Bujumbura", "quartier": "Sud",                "avenue": "Avenue 3", "maison": "56", "role": "membre", "groupe_id": 1            }        ]        for u in users:            conn.execute(                text("""                    INSERT INTO membres (telephone, pin, nom, prenom, age, sexe, cni, colline, quartier, avenue, maison, role, groupe_id, is_active, doit_changer_pin)                    VALUES (:telephone, :pin, :nom, :prenom, :age, :sexe, :cni, :colline, :quartier, :avenue, :maison, :role, :groupe_id, 1, 1)                    ON CONFLICT (telephone)                     DO UPDATE SET                         pin = EXCLUDED.pin,                         role = EXCLUDED.role,                         nom = EXCLUDED.nom,                         prenom = EXCLUDED.prenom,                        groupe_id = EXCLUDED.groupe_id                """),                u            )init_db()def get_burundi_weather_and_time():    try:        url = "https://api.openweathermap.org/data/2.5/weather?q=Bujumbura&units=metric&appid=e6293f9c3f392233f2d250325fa1292a"        response = requests.get(url, timeout=3)        if response.status_code == 200:            data = response.json()            temp = round(data["main"]["temp"])            desc = data["weather"][0]["description"]            weather_str = f"{temp}°C ({desc.capitalize()})"        else:            weather_str = "18°C (Partiellement nuageux)"    except Exception:        weather_str = "18°C (Données locales)"    now = datetime.now().strftime("%A %d %B %Y - %H:%M:%S")    return now, weather_strdef render_header_banner():    current_time, weather_info = get_burundi_weather_and_time()    st.info(f"📅 **Date & Heure (Bujumbura) :** {current_time} | 🌡️ **Météo Burundi :** {weather_info}")def log_audit(user, action, details):    try:        with engine.begin() as conn:            conn.execute(                text("INSERT INTO logs (utilisateur, action, details, date) VALUES (:user, :action, :details, :date)"),                {"user": user, "action": action, "details": details,                 "date": datetime.now().strftime("%Y-%m-%d %H:%M:%S")}            )    except Exception as e:        print(f"Erreur d'audit : {e}")def login_page():    render_header_banner()    st.markdown("<h1 style='text-align: center;'>🏦 SACCO Connect</h1>", unsafe_allow_html=True)    st.write("---")    tab_connexion, tab_inscription = st.tabs(["🔐 Connexion Sécurisée", "📝 Devenir Membre"])    with tab_connexion:        st.subheader("Accès à votre espace membre")        with st.form("login_form"):            telephone = st.text_input("Numéro de Téléphone (Identifiant)", placeholder="Ex: +257XXXXXXXX")            password = st.text_input("Code PIN", type="password")            submit_btn = st.form_submit_button("Accéder au Système")            if submit_btn:                if not telephone or not password:                    st.warning("⚠️ Veuillez remplir tous les champs.")                else:                    try:                        login_data = LoginRequest(telephone=telephone, pin=password)                        df_user = pd.read_sql("SELECT * FROM membres WHERE telephone = %s", engine, params=(login_data.telephone,))                        if not df_user.empty:                            user_row = df_user.iloc[0]                            stored_password = user_row.get('pin', '')                            hashed_input_pwd = hashlib.sha256(login_data.pin.encode()).hexdigest()                            if stored_password == hashed_input_pwd or stored_password == login_data.pin:                                st.session_state.logged_in = True                                st.session_state.user = user_row.to_dict()                                st.session_state.user_data = user_row.to_dict()                                st.success(f"🎉 Bienvenue, {user_row.get('prenom', '')} {user_row.get('nom', '')} !")                                st.rerun()                            else:                                st.error("❌ Code PIN incorrect.")                        else:                            st.error("❌ Aucun compte associé à ce numéro de téléphone.")                    except Exception as e:                        st.error(f"🚨 Erreur de connexion : {e}")    with tab_inscription:        st.markdown("### 📄 Formulaire d'Adhésion Officiel")        with st.form("inscription_form"):            col1, col2 = st.columns(2)            with col1:                nom = st.text_input("Nom")                cni = st.text_input("Numéro de Carte d'Identité (CNI)")                sexe = st.selectbox("Sexe", ["M", "F"])            with col2:                prenom = st.text_input("Prénom")                age = st.number_input("Âge", min_value=18, max_value=120, value=18)                telephone_ins = st.text_input("Téléphone (Identifiant)")            col3, col4 = st.columns(2)            with col3:                colline = st.text_input("Colline")                avenue = st.text_input("Avenue / Rue")            with col4:                quartier = st.text_input("Quartier")                maison = st.text_input("N° Maison")            pin_ins = st.text_input("Définir un Code PIN", type="password")            submit_ins = st.form_submit_button("Valider mon Inscription")            if submit_ins:                if not telephone_ins or not pin_ins or not nom:                    st.warning("⚠️ Veuillez remplir les champs obligatoires.")                else:                    try:                        payload = InscriptionPayload(                            telephone=telephone_ins, colline=colline, quartier=quartier,                            avenue=avenue, maison=maison, nom=nom, prenom=prenom,                            age=int(age), sexe=sexe, cni=cni                        )                        hashed_pin = hashlib.sha256(pin_ins.encode()).hexdigest()                        insert_query = """                            INSERT INTO membres (telephone, pin, nom, prenom, age, sexe, cni, colline, quartier, avenue, maison, role, groupe_id, is_active)                            VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, 'MEMBRE', 1, 1)                        """                        with engine.begin() as conn:                            conn.execute(                                text(insert_query),                                (payload.telephone, hashed_pin, payload.nom, payload.prenom, payload.age, payload.sexe,                                 payload.cni, payload.colline, payload.quartier, payload.avenue, payload.maison)                            )                        st.success("✅ Adhésion validée avec succès ! Vous pouvez vous connecter.")                    except Exception as e:                        st.error(f"❌ Erreur lors de l'inscription : {e}")def afficher_previsions_ia(membre_id):    st.write("---")    st.subheader("📈 Prévisions Financières par IA")    col1, col2 = st.columns(2)    with col1:        st.write("---")        if st.button("🔮 Prédire Épargne"):            st.info(f"Épargne estimée le mois prochain : En développement")    with col2:        st.write("---")        if st.button("🔮 Prédire Capacité Crédit"):            st.warning(f"Capacité de crédit estimée : En développement")# ==========================================# GESTION DES ARCHIVES SANS LA CLASSE PDF# ==========================================def generer_certificat_archive(membre_data):    dette = membre_data.get('solde_pret', 0) + membre_data.get('solde_pret_social', 0)    net = membre_data.get('solde_epargne', 0) - dette    net_a_restituer = max(0, net)    contenu = f"""==================================================        CERTIFICAT DE CLÔTURE DE COMPTE - SACCO==================================================DÉTAILS DU MEMBRE-----------------Nom & Prénom : {membre_data['nom']} {membre_data['prenom']}Téléphone    : {membre_data['telephone']}ID Système   : {membre_data['id']}ÉTAT FINANCIER FINAL--------------------Total Épargne Cumulée : {membre_data.get('solde_epargne', 0):,.0f} BIFTotal Dettes / Prêts  : {dette:,.0f} BIFMONTANT NET À RESTITUER : {net_a_restituer:,.0f} BIF==================================================Généré le : {datetime.now().strftime("%Y-%m-%d %H:%M")}"""    chemin_final = f"certificat_{membre_data['id']}.txt"    with open(chemin_final, "w", encoding="utf-8") as f:        f.write(contenu)    return chemin_finaldef interface_blocage_membre(current_user):    st.header("🚫 Gestion des Départs & Blocages")    if current_user['role'] == "admin_sys":        query = "SELECT * FROM membres WHERE is_active = 1"        params = ()    else:        query = "SELECT * FROM membres WHERE groupe_id = %s AND is_active = 1"        params = (current_user['groupe_id'],)    df_actifs = pd.read_sql(query, engine, params=params)    if not df_actifs.empty:        df_actifs['nom_complet'] = df_actifs['id'].astype(str) + " - " + df_actifs['nom'] + " " + df_actifs['prenom']        membre_selectionne = st.selectbox("Sélectionner le membre à bloquer", df_actifs['nom_complet'].tolist())        target_id = int(membre_selectionne.split(" - ")[0])        membre_data = df_actifs[df_actifs['id'] == target_id].iloc[0].to_dict()        st.warning(f"⚠️ Vous êtes sur le point de bloquer {membre_data['nom']}.")        if st.button("Confirmer le blocage et générer le certificat"):            cur = db_conn.cursor()            try:                cur.execute("UPDATE membres SET is_active = 0 WHERE id = %s", (target_id,))                db_conn.commit()                # Génère désormais un .txt pour contourner le manque de SaccoPDF                doc_path = generer_certificat_archive(membre_data)                log_audit(current_user['nom'], "BLOCAGE", f"Membre {target_id} archivé")                st.session_state['doc_a_telecharger'] = doc_path                st.session_state['msg_succes'] = f"✅ {membre_data['nom']} a été archivé."            except Exception as e:                db_conn.rollback()                st.error(f"Erreur lors de l'archivage : {e}")            finally:                cur.close()            st.rerun()        if 'doc_a_telecharger' in st.session_state:            st.success(st.session_state.get('msg_succes', 'Fichier prêt'))            try:                with open(st.session_state['doc_a_telecharger'], "rb") as f:                    st.download_button(                        label="📥 Télécharger le Certificat de Clôture (.txt)",                        data=f,                        file_name="Certificat_Cloture.txt",                        mime="text/plain"                    )            except Exception:                st.error("Le fichier a été déplacé ou supprimé.")            if st.button("Terminer l'opération"):                if os.path.exists(st.session_state['doc_a_telecharger']):                    os.remove(st.session_state['doc_a_telecharger'])                del st.session_state['doc_a_telecharger']                if 'msg_succes' in st.session_state:                    del st.session_state['msg_succes']                st.rerun()    else:        st.info("Aucun membre actif à bloquer.")def gestion_statut_membre(current_user):    st.subheader("🚫 Blocage & Archivage des Membres")    if current_user['role'] == "admin_sys":        query = "SELECT * FROM membres WHERE role != 'admin_sys'"        params = ()    else:        query = "SELECT * FROM membres WHERE groupe_id = %s AND role = 'membre'"        params = (current_user['groupe_id'],)    df_m = pd.read_sql(query, engine, params=params)    if not df_m.empty:        df_m['statut_txt'] = df_m['is_active'].apply(lambda x: "✅ Actif" if x == 1 else "📁 Archivé")        df_m['label'] = df_m['id'].astype(str) + " - " + df_m['prenom'] + " " + df_m['nom'] + " (" + df_m[            'statut_txt'] + ")"        membre_sel = st.selectbox("Sélectionner un membre", df_m['label'].tolist())        target_id = int(membre_sel.split(" - ")[0])        target_data = df_m[df_m['id'] == target_id].iloc[0].to_dict()        current_status = target_data['is_active']        col1, col2 = st.columns(2)        # Gestion du blocage        if current_status == 1:            if col1.button("🔒 Bloquer & Générer Certificat"):                cur = db_conn.cursor()                try:                    cur.execute("UPDATE membres SET is_active = 0 WHERE id = %s", (target_id,))                    db_conn.commit()                    log_audit(current_user['nom'], "ARCHIVAGE", f"Membre {target_id} archivé")                    # Génération TXT et stockage en session (Adapté suite au retrait de SaccoPDF)                    doc_file = generer_certificat_archive(target_data)                    st.session_state['doc_a_telecharger'] = doc_file                    st.session_state['msg_succes'] = f"✅ {target_data['nom']} archivé."                except Exception as e:                    db_conn.rollback()                    st.error(f"Erreur : {e}")                finally:                    cur.close()                st.rerun()            if st.session_state.get('doc_a_telecharger'):                st.success(st.session_state.get('msg_succes', 'Fichier prêt'))                try:                    with open(st.session_state['doc_a_telecharger'], "rb") as f:                        st.download_button(                            label="📥 Télécharger le Certificat de Clôture (.txt)",                            data=f,                            file_name="Certificat_Cloture.txt",                            mime="text/plain"                        )                except Exception:                    st.error("Fichier introuvable ou déjà supprimé.")        # Gestion de la réactivation        else:            if col2.button("🔓 Débloquer / Réactiver"):                cur = db_conn.cursor()                try:                    cur.execute("UPDATE membres SET is_active = 1 WHERE id = %s", (target_id,))                    db_conn.commit()                    log_audit(current_user['nom'], "REACTIVATION", f"Membre {target_id} réactivé")                    st.success("✅ Membre réactivé avec succès.")                except Exception as e:                    db_conn.rollback()                    st.error(f"Erreur : {e}")                finally:                    cur.close()                st.rerun()def predict_savings(membre_id):    try:        query = "SELECT montant FROM historique_epargne WHERE membre_id = %s"        df_hist = pd.read_sql_query(query, engine, params=(membre_id,))        if not df_hist.empty and len(df_hist) > 1:            return df_hist['montant'].mean() * 1.05        return 50000    except Exception as e:        st.error(f"Erreur prédiction épargne : {e}")        return 50000def predict_credit(membre_id):    try:        cursor = db_conn.cursor()        cursor.execute("SELECT solde_epargne FROM membres WHERE id = %s", (membre_id,))        result = cursor.fetchone()        cursor.close()        # Sécurisation : évite le crash si result[0] est None        solde = result[0] if result and result[0] is not None else 0        return solde * 3    except Exception as e:        st.error(f"Erreur prédiction crédit : {e}")        return 0# ==========================================# FONCTIONNALITÉ : RÉINITIALISATION DU PIN# ==========================================def reset_pin_ui(current_user):    if current_user['role'] == "admin_sys":        st.info("💡 En tant qu'Admin Système, vous pouvez réinitialiser n'importe quel membre.")        query = "SELECT id, nom, prenom, telephone, groupe_id FROM membres WHERE role != 'admin_sys'"        params = ()    else:        st.info(f"💡 Vous pouvez réinitialiser les membres de votre Groupe (ID: {current_user['groupe_id']})")        query = "SELECT id, nom, prenom, telephone, groupe_id FROM membres WHERE groupe_id = %s AND role = 'membre'"        params = (current_user['groupe_id'],)    list_members = pd.read_sql(query, engine, params=params)    if not list_members.empty:        list_members['display'] = list_members['id'].astype(str) + " - " + list_members['prenom'] + " " + list_members[            'nom'] + " (Tel: " + list_members['telephone'] + ")"        member_to_reset = st.selectbox("Sélectionner le membre par son ID", list_members['display'].tolist())        target_id = int(member_to_reset.split(" - ")[0])        new_pin = st.text_input("Nouveau Code PIN provisoire", type="password", help="Minimum 4 chiffres")        confirm_pin = st.text_input("Confirmer le PIN provisoire", type="password")        if st.button("Confirmer la réinitialisation"):            if new_pin == confirm_pin and len(new_pin) >= 4:                h_pin = pwd_context.hash(new_pin)                cur = db_conn.cursor()                try:                    cur.execute(                        "UPDATE membres SET pin = %s, doit_changer_pin = 1 WHERE id = %s",                        (h_pin, target_id)                    )                    db_conn.commit()                    log_audit(current_user['nom'], "RESET_PIN", f"PIN réinitialisé pour l'ID {target_id}")                    st.success(f"✅ Le code PIN de l'ID {target_id} a été mis à jour avec succès.")                except Exception as e:                    db_conn.rollback()                    st.error(f"❌ Erreur lors de la mise à jour : {e}")                finally:                    cur.close()            else:                st.error("⚠️ Les codes PIN ne correspondent pas ou sont trop courts (minimum 4 chiffres).")# ==========================================# INTERFACE PRINCIPALE (MULTI-RÔLES)# ==========================================if st.session_state.user:    u = st.session_state.user    role = str(u['role']).lower()    gid = u.get('groupe_id')    with st.sidebar:        try:            st.image("sac.jpg", width=120)        except:            pass        st.write(f"👤 **{u['prenom']} {u['nom']}**")        st.caption(f"Rôle : {role.upper()} | Groupe : #{gid}")        st.write("---")        if role == "admin":            menu = ["Vue Panoramique", "Gestion des Membres", "Paramètres Groupe", "Scanner Présences", "Audit Global",                    "Configuration Système"]        elif role in ["president", "secretaire"]:            menu = ["Mon Profil", "Mon Compte", "Demande de Prêt", "Historique", "Saisie Hebdomadaire",                    "Tableau du Groupe", "Gestion des Prêts", "Scanner Présences", "Audit de Mon groupe",                    "Paramètres Groupe"]        else:            menu = ["Mon Profil", "Mon Compte", "Demande de Prêt", "Historique"]        choice = st.selectbox("Menu de Navigation", menu)        st.write("---")        if st.button("🚪 Quitter la session"):            st.session_state.user = None            st.rerun()    # --- 5.1 ESPACE ADMINISTRATEUR SYSTÈME ---    if role == "admin":        if choice == "Vue Panoramique":            st.title("🛡️ Tableau de Bord de l'Audit Système")            current_time, weather_info = get_burundi_weather_and_time()            st.info(f"📅 **Date & Heure (Bujumbura) :** {current_time} | 🌡️ **Météo Burundi :** {weather_info}")            m_df = pd.read_sql("SELECT * FROM membres", engine)            p_df = pd.read_sql("SELECT * FROM prets", engine)            c1, c2, c3, c4 = st.columns(4)            c1.metric("Total Membres", len(m_df))            c2.metric("Épargne Totale", f"{m_df['solde_epargne'].sum():,.0f} BIF")            c3.metric("Prêts en Cours", f"{m_df['solde_pret'].sum():,.0f} BIF")            c4.metric("Groupes Actifs", pd.read_sql("SELECT COUNT(*) FROM groupes", engine).iloc[0, 0])            st.write("---")            afficher_previsions_ia(u['id'])            tab_logs, tab_epargnes = st.tabs(                ["🖥️ Analyses & Logs d'Activités", "💰 Historique des Épargnes des Membres"])            with tab_logs:                st.subheader("📊 Graphique de Répartition & Activité")                fig = px.pie(m_df, values='solde_epargne', names='nom', title="Répartition de l'Épargne Nationale")                st.plotly_chart(fig, use_container_width=True)                st.write("---")                st.subheader("📜 Logs récents du système")                logs_df = pd.read_sql("SELECT * FROM logs ORDER BY date DESC LIMIT 20", engine)                st.dataframe(logs_df, use_container_width=True)            with tab_epargnes:                st.subheader("📊 Registre Général des Épargnes")                st.write("---")                query_historique = """                    SELECT                         m.nom || ' ' || m.prenom AS "Nom du Membre",                         g.nom_groupe AS "Groupe",                         h.montant AS "Montant (BIF)",                         h.date_reunion AS "Date Enregistrement",                         h.heure_enregistrement AS "Heure",                         h.enregistre_par AS "Enregistré Par"                     FROM historique_epargne h                     JOIN membres m ON h.membre_id = m.id                     JOIN groupes g ON m.groupe_id = g.id                     ORDER BY h.date_reunion DESC, h.heure_enregistrement DESC                """                try:                    df_global = pd.read_sql_query(query_historique, engine)                    if not df_global.empty:                        c_filtre1, c_filtre2 = st.columns(2)                        liste_groupes = ["Tous les groupes"] + list(df_global["Groupe"].unique())                        choix_groupe = c_filtre1.selectbox("📁 Filtrer par groupe :", liste_groupes)                        recherche = c_filtre2.text_input("🔍 Rechercher un membre :", "", key="search_admin_global")                        if choix_groupe != "Tous les groupes":                            df_global = df_global[df_global["Groupe"] == choix_groupe]                        if recherche:                            df_global = df_global[                                df_global["Nom du Membre"].str.contains(recherche, case=False, na=False)]                        st.write("---")                        c_aud1, c_aud2 = st.columns(2)                        total_flux = pd.to_numeric(df_global['Montant (BIF)'], errors='coerce').sum()                        c_aud1.metric("💵 Total des Flux d'Épargne", f"{total_flux:,.0f} BIF")                        c_aud2.metric("🔢 Nombre Total de Transactions", f"{len(df_global)} entrées")                        df_rendu_admin = df_global.copy()                        df_rendu_admin["Montant (BIF)"] = pd.to_numeric(df_rendu_admin["Montant (BIF)"],                                                                        errors='coerce').apply(                            lambda x: f"{x:,.0f} BIF" if pd.notnull(x) else "0 BIF"                        )                        st.dataframe(df_rendu_admin, use_container_width=True, hide_index=True)                        csv = df_global.to_csv(index=False).encode('utf-8')                        st.download_button(                            label="📥 Télécharger le registre (CSV)",                            data=csv,                            file_name="registre_general_epargnes.csv",                            mime="text/csv",                        )                    else:                        st.info("ℹ️ Aucune transaction d'épargne n'a encore été enregistrée dans le système.")                except Exception as e:                    st.error(f"Erreur technique lors de la récupération du registre global : {e}")        elif choice == "Gestion des Membres":            st.subheader("👥 Gestion, Déplacement et Création de Groupes")            st.write("---")            def assigner_membres_automatiquement(engine, db_conn):                cursor = db_conn.cursor()                try:                    df_sans_groupe = pd.read_sql("SELECT id FROM membres WHERE groupe_id IS NULL OR groupe_id = 0",                                                 engine)                    if df_sans_groupe.empty:                        st.info("💡 Aucun membre orphelin (sans groupe) à répartir.")                        return                    for membre_id in df_sans_groupe['id']:                        cursor.execute("""                            SELECT g.id, COUNT(m.id) as effectif                             FROM groupes g                             LEFT JOIN membres m ON g.id = m.groupe_id AND m.is_active = 1                            WHERE g.is_active = 1                            GROUP BY g.id                            HAVING COUNT(m.id) < 30                            LIMIT 1                        """)                        row = cursor.fetchone()                        if row:                            groupe_cible_id = row[0]                        else:                            cursor.execute("SELECT COUNT(*) FROM groupes")                            nb_groupes = cursor.fetchone()[0]                            nouveau_nom = f"Groupe Auto #{nb_groupes + 1}"                            cursor.execute("INSERT INTO groupes (nom_groupe, is_active) VALUES (%s, 1) RETURNING id",                                           (nouveau_nom,))                            groupe_cible_id = cursor.fetchone()[0]                            db_conn.commit()                        cursor.execute("UPDATE membres SET groupe_id = %s WHERE id = %s", (groupe_cible_id, membre_id))                        db_conn.commit()                    st.success("✅ Répartition automatique des membres effectuée avec succès (Max 30 par groupe).")                except Exception as e:                    db_conn.rollback()                    st.error(f"Erreur lors de l'affectation automatique : {e}")                finally:                    cursor.close()            col_bt1, col_bt2 = st.columns(2)            with col_bt1:                if st.button("🚀 Initialiser les chefs de groupe"):                    creer_bureau_executif()                    st.success("Opération exécutée.")            with col_bt2:                if st.button("🤖 Répartir automatiquement les membres (Max 30/groupe)"):                    assigner_membres_automatiquement(engine, db_conn)                    st.rerun()            all_m = pd.read_sql("SELECT id, nom, prenom, telephone, role, groupe_id, last_login FROM membres", engine)            st.dataframe(all_m, use_container_width=True)            # 1. MODIFICATION DE MEMBRE            with st.expander("📝 Modifier ou Déplacer un Membre"):                m_id = st.number_input("ID du Membre à modifier", step=1, min_value=1)                role_map = {                    "Membre": "membre",                    "Nommer Président de Groupe": "president",                    "Nommer Secrétaire de Groupe": "secretaire"                }                role_display = st.selectbox("Nouveau Rôle", list(role_map.keys()))                new_role_sql = role_map[role_display]                new_grp = st.number_input("Affecter au Groupe (ID)", step=1, value=1, min_value=1)                if st.button("💾 Appliquer les Changements"):                    check_taille = pd.read_sql(                        "SELECT COUNT(*) as effectif FROM membres WHERE groupe_id = %s AND is_active = 1",                        engine, params=(new_grp,)                    )                    effectif_actuel = check_taille.iloc[0]['effectif']                    if effectif_actuel >= 30:                        st.error("🚫 Impossible : Groupe saturé (30/30).")                    else:                        cursor = db_conn.cursor()                        try:                            cursor.execute("UPDATE membres SET role=%s, groupe_id=%s WHERE id=%s",                                           (new_role_sql, new_grp, m_id))                            db_conn.commit()                            log_audit(u['nom'], "MODIF_MEMBRE", f"ID {m_id} -> Role: {new_role_sql}, Grp: {new_grp}")                            st.success("✅ Modifications enregistrées.")                        except Exception as e:                            db_conn.rollback()                            st.error(f"Erreur : {e}")                        finally:                            cursor.close()                        st.rerun()            st.write("---")            # 2. CRÉATION DE NOUVEAU GROUPE            with st.expander("➕ Créer Manuellement un Nouveau Groupe"):                st.write("### 🏗️ Formulaire de configuration du Groupe")                c_grp1, c_grp2 = st.columns(2)                nom_nouveau_groupe = c_grp1.text_input("Nom du Nouveau Groupe", key="new_g_nom")                c_grp3, c_grp4 = st.columns(2)                nom_pres_init = c_grp3.text_input("Nom & Prénom du Président désigné (Info)", key="new_g_pres")                nom_sec_init = c_grp4.text_input("Nom & Prénom du Secrétaire désigné (Info)", key="new_g_sec")                if st.button("🏗️ Valider et Créer le Groupe"):                    if not nom_nouveau_groupe or not nom_nouveau_groupe.strip():                        st.warning("⚠️ Veuillez donner un nom valide au groupe.")                    else:                        cursor = db_conn.cursor()                        try:                            cursor.execute("ALTER TABLE groupes ADD COLUMN IF NOT EXISTS is_active INTEGER DEFAULT 1")                            db_conn.commit()                            cursor.execute("""                                INSERT INTO groupes (nom_groupe, is_active)                                 VALUES (%s, 1) RETURNING id""",                                           (nom_nouveau_groupe.strip(),)                                           )                            new_id_genere = cursor.fetchone()[0]                            db_conn.commit()                            st.success(                                f"🎉 Groupe #{new_id_genere} '{nom_nouveau_groupe}' créé ! Attribuez maintenant le président et secrétaire via le menu 'Modifier un membre' ci-dessus.")                        except Exception as e:                            db_conn.rollback()                            st.error(f"❌ Erreur lors de la création : {e}")                        finally:                            cursor.close()            # 3. SUPPRESSION / ARCHIVAGE DE GROUPE            with st.expander("🗑️ Gestion & Suppression de Groupes"):                st.write("### 🚫 Supprimer un groupe existant")                st.warning("⚠️ RAPPEL : Un groupe supprimé est archivé et devient non fonctionnel.")                try:                    cur_test = db_conn.cursor()                    cur_test.execute("ALTER TABLE groupes ADD COLUMN IF NOT EXISTS is_active INTEGER DEFAULT 1")                    db_conn.commit()                    cur_test.close()                    df_groupes_actifs = pd.read_sql_query("SELECT id, nom_groupe FROM groupes WHERE is_active = 1",                                                          db_conn)                except Exception as e:                    df_groupes_actifs = pd.DataFrame()                    st.error(f"Erreur de lecture : {e}")                if df_groupes_actifs.empty:                    st.info("💡 Aucun groupe actif disponible.")                else:                    options_grps = {row['id']: f"Groupe #{row['id']} - {row['nom_groupe']}" for _, row in                                    df_groupes_actifs.iterrows()}                    grp_a_supprimer = st.selectbox("Sélectionnez le groupe :", options=list(options_grps.keys()),                                                   format_func=lambda x: options_grps[x])                    confirm = st.checkbox(f"Confirmer la suppression du {options_grps[grp_a_supprimer]}.")                    if st.button("🗑️ Supprimer le groupe", type="primary"):                        if confirm:                            cursor = db_conn.cursor()                            try:                                cursor.execute("UPDATE groupes SET is_active = 0 WHERE id = %s", (grp_a_supprimer,))                                cursor.execute("UPDATE membres SET is_active = 0 WHERE groupe_id = %s",                                               (grp_a_supprimer,))                                db_conn.commit()                                st.success("✅ Groupe archivé avec succès !")                                st.rerun()                            except Exception as e:                                db_conn.rollback()                                st.error(f"❌ Erreur : {e}")                            finally:                                cursor.close()                        else:                            st.error("❌ Cochez la case de confirmation.")        elif choice == "Paramètres Groupe":            st.subheader("⚙️ Administration du Groupe")            # 1. Gestion unifiée du rôle et du groupe            gid = u.get('groupe_id')            # Si l'utilisateur est admin système ou admin global sans groupe assigné            if role in ["admin_sys", "admin"] and gid is None:                st.info("💡 Veuillez sélectionner un groupe à administrer :")                liste_g = pd.read_sql("SELECT id, nom_groupe FROM groupes", engine)                if not liste_g.empty:                    choix_g = st.selectbox(                        "Sélectionner le groupe :",                        options=liste_g['id'].tolist(),                        format_func=lambda x: f"Groupe #{x} - {liste_g[liste_g['id'] == x]['nom_groupe'].values[0]}"                    )                    gid = choix_g                else:                    st.error("⚠️ Aucun groupe existant dans la base de données.")                    st.stop()            # 2. Sécurité anti-plantage finale            if gid is None:                st.error("🚫 Aucun groupe assigné ou sélectionné.")                st.stop()            # 3. Création des onglets            tab1, tab2, tab3, tab4 = st.tabs([                "📆 Réunions & Cotisations",                "📊 Simulateur Financier",                "🔐 Sécurité PIN",                "🚫 Gestion des accès"            ])            # --- ONGLET 1 : RÉUNIONS ---            with tab1:                if role == "admin_sys":                    st.info(                        "💡 En tant qu'Admin Système, utilisez l'onglet de simulation pour choisir un groupe spécifique.")                st.write("### Configuration des réunions")                next_date = st.date_input("Définir la prochaine réunion", key="next_meeting")                new_hebdo = st.number_input("Montant de la cotisation hebdomadaire (BIF)", value=5000, step=500)                if role == "admin_sys" and gid is None:                    st.warning(                        "Veuillez sélectionner un groupe via le tableau de bord principal pour modifier ses réglages.")                else:                    if st.button("Enregistrer les réglages du groupe"):                        cur = db_conn.cursor()                        try:                            cur.execute(                                "UPDATE groupes SET date_reunion_prochaine=%s, montant_hebdo=%s WHERE id=%s",                                (str(next_date), new_hebdo, gid)                            )                            db_conn.commit()                            log_audit(u['nom'], "CONFIG_GROUPE", f"Nouveau montant: {new_hebdo}")                            st.success("✅ Paramètres du groupe mis à jour.")                            st.rerun()                        except Exception as e:                            db_conn.rollback()                            st.error(f"❌ Erreur lors de la mise à jour : {e}")                        finally:                            cur.close()            # --- ONGLET 2 : SIMULATEUR ---            with tab2:                st.write("### 📈 Simulateur de Performance Financière")                if role == "admin_sys":                    liste_groupes = pd.read_sql("SELECT id, nom_groupe FROM groupes", engine)                    if not liste_groupes.empty:                        choix_groupe = st.selectbox(                            "🔍 Sélectionner le groupe à analyser :",                            options=liste_groupes['id'].tolist(),                            format_func=lambda                                x: f"Groupe #{x} - {liste_groupes[liste_groupes['id'] == x]['nom_groupe'].values[0]}"                        )                        id_groupe_simulation = choix_groupe                    else:                        st.error("⚠️ Aucun groupe disponible.")                        st.stop()                else:                    id_groupe_simulation = gid                    st.write(f"📍 *Simulation basée sur votre groupe actuel (ID: {gid})*")                try:                    group_q = pd.read_sql(                        "SELECT nom_groupe, taux_amende, date_reunion_derniere, date_reunion_prochaine FROM groupes WHERE id = %s",                        engine, params=(id_groupe_simulation,)                    )                    if not group_q.empty:                        amende_unitaire = group_q.iloc[0]['taux_amende'] or 1000                        nom_groupe_sim = group_q.iloc[0]['nom_groupe']                        date_derniere = group_q.iloc[0]['date_reunion_derniere'] or "Non définie"                        date_prochaine = group_q.iloc[0]['date_reunion_prochaine'] or "À déterminer"                    else:                        st.error("⚠️ Impossible de charger les données du groupe.")                        st.stop()                    df_membres_sim = pd.read_sql(                        "SELECT id, nom, prenom, solde_epargne FROM membres WHERE groupe_id = %s AND is_active = 1",                        engine,                        params=(id_groupe_simulation,)                    )                    if df_membres_sim.empty:                        st.warning(                            f"⚠️ Aucun membre actif dans le groupe '{nom_groupe_sim}' pour exécuter les simulations.")                    else:                        st.markdown("#### 📅 1. Projection Globale des Intérêts (Période de 3 mois)")                        st.caption(                            f"Basé sur l'état post-réunion hebdomadaire. Dernier calendrier saisi : Du **{date_derniere}** au **{date_prochaine}**.")                        taux_annuel_sim = st.number_input("Taux d'intérêt annuel cible (%)", 0.0, 20.0, 5.0, step=0.5,                                                          key="tx_an_3m")                        # Calcul prorata 3 mois                        taux_trimestriel = taux_annuel_sim / 4                        mult_trimestriel = 1 + (taux_trimestriel / 100)                        list_rows_interets = []                        total_interets_injectes = 0                        for _, membre in df_membres_sim.iterrows():                            solde_actuel = membre['solde_epargne'] or 0                            nouveau_solde = solde_actuel * mult_trimestriel                            interet_gagne = nouveau_solde - solde_actuel                            total_interets_injectes += interet_gagne                            list_rows_interets.append({                                "ID": f"#00{membre['id']}",                                "Nom & Prénom": f"{membre['nom']} {membre['prenom']}",                                "Épargne Actuelle (BIF)": f"{solde_actuel:,.0f}",                                "Intérêts Générés (3 mois)": f"+{interet_gagne:,.0f}",                                "Solde Estimé après 3 mois": f"{nouveau_solde:,.0f}"                            })                        st.dataframe(pd.DataFrame(list_rows_interets), use_container_width=True)                        st.success(                            f"📈 Total des intérêts théoriques injectés dans le groupe sur 3 mois : **+{total_interets_injectes:,.0f} BIF** (Taux appliqué : {taux_trimestriel:.3f}%)")                        st.write("---")                        st.markdown("#### 🚫 2. Simulateur de Retard Individuel (Période de 1 mois)")                        st.caption(                            "Permet d'évaluer l'impact financier des retards de paiement répétés pour un membre spécifique sur un mois d'activité.")                        membre_options = df_membres_sim.apply(lambda r: f"{r['nom']} {r['prenom']} (ID: #00{r['id']})",                                                              axis=1).tolist()                        membre_selectionne_str = st.selectbox("🎯 Choisir le membre en retard de paiement :",                                                              options=membre_options)                        idx_selectionne = membre_options.index(membre_selectionne_str)                        membre_cible = df_membres_sim.iloc[idx_selectionne]                        nb_retards_mois = st.number_input(                            f"Nombre de retards de paiement ce mois pour {membre_cible['prenom']}", 1, 5, 2, step=1)                        amende_totale_mois = nb_retards_mois * amende_unitaire                        solde_actuel_membre = membre_cible['solde_epargne'] or 0                        solde_apres_amende = max(0, solde_actuel_membre - amende_totale_mois)                        st.markdown(f"""                                    <div style="background-color: #fff5f5; padding: 20px; border-radius: 12px; border-left: 6px solid #e74c3c; margin-top: 15px;">                                        <h5 style="color: #c0392b; margin-top:0;">⚠️ Rapport de Simulation d'Amende - {membre_cible['nom']} {membre_cible['prenom']}</h5>                                        <table style="width: 100%; border-collapse: collapse;">                                            <tr>                                                <td style="padding: 5px 0;"><b>Solde d'Épargne Actuel :</b></td>                                                <td style="text-align: right;">{solde_actuel_membre:,.0f} BIF</td>                                            </tr>                                            <tr>                                                <td style="padding: 5px 0; color: #c0392b;"><b>Amendes cumulées (sur 1 mois) :</b></td>                                                <td style="text-align: right; color: #c0392b; font-weight: bold;">-{amende_totale_mois:,.0f} BIF</td>                                            </tr>                                            <tr style="border-top: 1px solid #ddd;">                                                <td style="padding: 8px 0; font-size: 1.05em;"><b>Solde de sécurité projeté :</b></td>                                                <td style="text-align: right; font-size: 1.05em; font-weight: bold; color: #2c3e50;">{solde_apres_amende:,.0f} BIF</td>                                            </tr>                                        </table>                                        <p style="font-size: 0.85em; color: #7f8c8d; margin: 10px 0 0 0;">                                            *Note : Le taux d'amende unitaire appliqué est celui fixé par le groupe {nom_groupe_sim},                                             soit <b>{amende_unitaire:,.0f} BIF</b> par retard/absence à la réunion hebdomadaire.*                                        </p>                                    </div>                                """, unsafe_allow_html=True)                except Exception as e:                    st.error(f"⚠️ Erreur lors du chargement des données pour la simulation : {e}")            # --- ONGLET 3 : SÉCURITÉ ---            with tab3:                st.write("### 🔐 Réinitialisation du code PIN")                if 'reset_pin_ui' in globals():                    reset_pin_ui(u)                else:                    st.error("Fonction de réinitialisation PIN introuvable.")            # --- ONGLET 4 : GESTION DES ACCÈS ---            with tab4:                st.write("### 🚫 Clôture de compte & Archivage")                st.warning("**Attention :** L'archivage d'un membre générera automatiquement un certificat de clôture.")                if 'gestion_statut_membre' in globals():                    gestion_statut_membre(u)                else:                    st.error("Fonction de gestion des accès introuvable.")            # --- 5.2 SCANNER PRÉSENCES ---        elif choice == "Scanner Présences":            st.header("📸 Émargement par Scanner QR Code")            st.info("💡 Autorisez l'accès à votre caméra, puis présentez le code QR du membre devant l'objectif.")            if role == "admin":                liste_g = pd.read_sql("SELECT id, nom_groupe FROM groupes", engine)                if not liste_g.empty:                    choix_g = st.selectbox(                        "Sélectionner le groupe de pointage :",                        options=liste_g['id'].tolist(),                        format_func=lambda x: f"Groupe #{x} - {liste_g[liste_g['id'] == x]['nom_groupe'].values[0]}"                    )                    current_gid = choix_g                else:                    st.error("⚠️ Aucun groupe existant dans la base de données.")                    st.stop()            else:                current_gid = u.get('groupe_id')            if current_gid is None:                st.error("🚫 Impossible de charger le scanner : Vous n'êtes assigné à aucun groupe.")                st.stop()            group_info = pd.read_sql(                "SELECT taux_amende, montant_hebdo FROM groupes WHERE id=%s",                engine,                params=(int(current_gid),)            )            if not group_info.empty:                taux_amende = group_info.iloc[0]['taux_amende']                montant_hebdo = group_info.iloc[0]['montant_hebdo']            else:                st.error("⚠️ Impossible de récupérer les configurations du groupe.")                st.stop()            img_file = st.camera_input("Scanner le Badge")            if img_file is not None:                file_bytes = np.asarray(bytearray(img_file.read()), dtype=np.uint8)                opencv_img = cv2.imdecode(file_bytes, 1)                detector = cv2.QRCodeDetector()                data, bbox, straight_qrcode = detector.detectAndDecode(opencv_img)                if data and data.startswith("SACCO_MEMBER_"):                    try:                        scanned_member_id = int(data.replace("SACCO_MEMBER_", ""))                        check_membre = pd.read_sql(                            "SELECT id, nom, prenom, groupe_id, is_active FROM membres WHERE id = %s",                            engine,                            params=(scanned_member_id,)                        )                        if check_membre.empty:                            st.error("❌ Code QR invalide : Ce membre n'existe pas dans le système.")                        else:                            m_data = check_membre.iloc[0]                            if m_data['is_active'] == 0:                                st.error(                                    f"🚫 Action impossible : Le compte de {m_data['prenom']} {m_data['nom']} est archivé ou bloqué.")                            # 4. CORRECTION ICI AUSSI : "admin" au lieu de "admin_sys" pour la sécurité                            elif role != "admin" and m_data['groupe_id'] != current_gid:                                st.error(                                    f"⚠️ Alerte sécurité : Ce membre appartient au Groupe #{m_data['groupe_id']} et non à votre groupe.")                            else:                                st.success(                                    f"🎉 Badge détecté avec succès ! Membre : **{m_data['nom']} {m_data['prenom']}**")                                st.write(                                    f"⚙️ **Écritures automatiques prévues :** Presence = 'P', Épargne = +{montant_hebdo} BIF")                                if st.button(f"💾 Confirmer l'Émargement de {m_data['prenom']}"):                                    cur_emargement = db_conn.cursor()                                    try:                                        cur_emargement.execute("""                                                            UPDATE membres SET                                                             solde_epargne = solde_epargne + %s,                                                             status_presence = 'P'                                                             WHERE id = %s""",                                                               (montant_hebdo, scanned_member_id)                                                               )                                        cur_emargement.execute(                                            "INSERT INTO historique_social (membre_id, montant, date_reunion) VALUES (%s, %s, %s)",                                            (scanned_member_id, 0, datetime.now().strftime('%Y-%m-%d'))                                        )                                        db_conn.commit()                                        log_audit(u['nom'], "EMARGEMENT_QR",                                                  f"Présence QR validée pour le membre ID {scanned_member_id}")                                        st.balloons()                                        st.success(                                            f"✅ Présence de {m_data['prenom']} {m_data['nom']} enregistrée en base de données !")                                    except Exception as e:                                        db_conn.rollback()                                        st.error(f"Erreur d'enregistrement : {e}")                                    finally:                                        cur_emargement.close()                                    st.rerun()                    except Exception as e:                        st.error(f"❌ Erreur lors du traitement du QR Code : {e}")                else:                    st.warning(                        "🔍 Aucun QR Code de la Sacco détecté. Ajustez la luminosité ou la distance de votre badge.")            # --- 5.3 AUDIT GLOBAL ---        elif choice == "Audit Global":            st.subheader("🕵️ Audit Complet des Transactions")            logs = pd.read_sql("SELECT * FROM logs ORDER BY id DESC", engine)            st.dataframe(logs, use_container_width=True)            st.write("---")            st.subheader("📋 Liste des comptes & Statuts")            filtre_statut = st.radio(                "Filtrer la vue :",                ["Membres Actifs", "Archives / Bloqués", "Tous"],                horizontal=True            )            query_base = "SELECT id, nom, prenom, telephone, role, is_active, groupe_id FROM membres WHERE 1=1"            params = []            if role != "admin_sys":                query_base += " AND groupe_id = %s"                params.append(u['groupe_id'])            if filtre_statut == "Membres Actifs":                query_base += " AND is_active = 1"            elif filtre_statut == "Archives / Bloqués":                query_base += " AND is_active = 0"            df_complet = pd.read_sql(query_base, engine, params=tuple(params))            st.dataframe(                df_complet.style.apply(                    lambda row: ['background-color: #ffcccc' if row.is_active == 0 else '' for _ in row], axis=1),                use_container_width=True            )            def exporter_excel_groupe_officiel(df_donnees, type_document="LISTE DES MEMBRES", info_groupe=None):                buf = io.BytesIO()                df_ajuste = df_donnees.copy()                lignes_manquantes = 30 - len(df_ajuste)                if lignes_manquantes > 0:                    lignes_vides = pd.DataFrame({col: [""] * lignes_manquantes for col in df_ajuste.columns})                    df_ajuste = pd.concat([df_ajuste, lignes_vides], ignore_index=True)                with pd.ExcelWriter(buf, engine='openpyxl') as writer:                    df_ajuste.to_excel(writer, index=False, sheet_name="Document_Officiel", startrow=8)                    worksheet = writer.sheets["Document_Officiel"]                    border_vide = Border(                        left=Side(border_style=None),                        right=Side(border_style=None),                        top=Side(border_style=None),                        bottom=Side(border_style=None)                    )                    nb_cols = max(len(df_ajuste.columns), 6)                    for r in [1, 2, 3, 4]:                        worksheet.merge_cells(start_row=r, start_column=3, end_row=r, end_column=nb_cols)                        for c in range(1, nb_cols + 1):                            worksheet.cell(row=r, column=c).border = border_vide                    worksheet.merge_cells(start_row=6, start_column=1, end_row=6, end_column=nb_cols)                    for c in range(1, nb_cols + 1):                        worksheet.cell(row=6, column=c).border = border_vide                    if os.path.exists("sac.jpg"):                        img = OpenpyxlImage("sac.jpg")                        img.width = 110                        img.height = 110                        worksheet.add_image(img, 'A1')                    cell_e1 = worksheet.cell(row=1, column=3, value="SACCO FINTECH BURUNDI")                    cell_e1.font = Font(name="Arial", size=13, bold=True, color="1C39BB")                    cell_e1.alignment = Alignment(horizontal="right", vertical="center")                    cell_titre = worksheet.cell(row=6, column=1, value=f"DOCUMENT OFFICIEL : {type_document.upper()}")                    cell_titre.font = Font(name="Arial", size=14, bold=True, color="C0392B")                    cell_titre.alignment = Alignment(horizontal="center", vertical="center")                    header_fill = PatternFill(start_color="2C3E50", end_color="2C3E50", fill_type="solid")                    header_font = Font(name="Arial", size=11, bold=True, color="FFFFFF")                    for col_num in range(1, len(df_ajuste.columns) + 1):                        cell = worksheet.cell(row=9, column=col_num)                        cell.fill = header_fill                        cell.font = header_font                        cell.alignment = Alignment(horizontal="center", vertical="center")                return buf.getvalue()            st.write("---")            st.write("#### 📥 Zone d'exportation des pièces justificatives")            nom_du_groupe = "Sacco FinTech - Administration Centrale"            nom_president = "NKURUNZIZA Raphael"            nom_secretaire = "Niyomwungere Jean"            if role != "admin_sys" and "groupe_id" in u:                try:                    info_db = pd.read_sql("SELECT nom_groupe FROM groupes WHERE id = %s", db_conn,                                          params=[u['groupe_id']])                    if not info_db.empty:                        nom_du_groupe = info_db.iloc[0]['nom_groupe']                except Exception:                    nom_du_groupe = f"Groupe ID #{u['groupe_id']}"            donnees_generales = {                "nom_groupe": nom_du_groupe,                "president": nom_president,                "secretaire": nom_secretaire            }            col_ex1, col_ex2 = st.columns(2)            with col_ex1:                st.write("📂 **Journal des Actions**")                excel_data_logs = exporter_excel_groupe_officiel(                    df_donnees=logs,                    type_document="Registre d'Audit des Transactions",                    info_groupe=donnees_generales                )                st.download_button(                    label="📥 Télécharger le Journal des Logs (Excel)",                    data=excel_data_logs,                    file_name=f"Audit_Transactions_{datetime.now().strftime('%Y%m%d')}.xlsx",                    mime="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",                    use_container_width=True                )            with col_ex2:                st.write("📂 **Registre de la Liste des Membres**")                excel_data_membres = exporter_excel_groupe_officiel(                    df_donnees=df_complet,                    type_document="Registre Officiel des Membres",                    info_groupe=donnees_generales                )                st.download_button(                    label="📥 Télécharger la Liste des Membres (Excel)",                    data=excel_data_membres,                    file_name=f"Registre_Membres_{datetime.now().strftime('%Y%m%d')}.xlsx",                    mime="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",                    use_container_width=True                )            st.write("---")            st.header("⚙️ Console d'Audit Général par Groupe")            st.info(                "🕵️‍♂️ Sélectionnez un groupe pour inspecter son registre d'enregistrement et l'activité de ses membres.")            try:                liste_groupes = pd.read_sql("SELECT id, nom_groupe FROM groupes ORDER BY id ASC", engine)                if not liste_groupes.empty:                    options_g = liste_groupes['id'].tolist()                    choix_admin_gid = st.selectbox(                        "🔍 Sélectionner le groupe à auditer :",                        options=options_g,                        format_func=lambda                            x: f"Groupe #{x} - {liste_groupes[liste_groupes['id'] == x]['nom_groupe'].values[0]}"                    )                    df_audit_groupe = pd.read_sql(                        "SELECT id, nom, prenom, role, solde_epargne, solde_pret, status_presence, is_active FROM membres WHERE groupe_id = %s",                        engine,                        params=(choix_admin_gid,)                    )                    if not df_audit_groupe.empty:                        m1, m2, m3 = st.columns(3)                        m1.metric("Membres dans ce groupe", len(df_audit_groupe))                        m2.metric("Épargne cumulée", f"{df_audit_groupe['solde_epargne'].sum():,.0f} BIF")                        m3.metric("Prêts en cours", f"{df_audit_groupe['solde_pret'].sum():,.0f} BIF")                        st.dataframe(df_audit_groupe, use_container_width=True)                    else:                        st.warning("Ce groupe ne contient aucun membre enregistré.")                else:                    st.error("⚠️ Aucun groupe créé dans le système.")            except Exception as e:                st.error(f"Erreur d'accès aux groupes : {e}")                tab_admin_membres, tab_admin_presences, tab_adm_sociale, tab_adm_epargne, tab_adm_decaissement, tab_adm_amendes, tab_adm_prets = st.tabs(                    [                        "👥 Liste des Membres",                        "📅 Suivi des Présences",                        "🏦 Caisse Sociale",                        "💰 Épargne & Cumuls",                        "💸 Décaissements Sociaux",                        "⚖️ Amendes",                        "📈 Journal des Prêts"                    ])                # =====================================================================                # 2️⃣ ONGLET ADMIN 1 : MEMBRES                # =====================================================================                with tab_admin_membres:                    st.subheader(f"📋 Registre d'Enregistrement - Groupe #{choix_admin_gid}")                    query_admin_audit = """                        SELECT                             id AS "N°",                             (prenom || ' ' || nom) AS "Noms et Prénoms",                             sexe AS "Sexe",                             age AS "Âge",                             telephone AS "Téléphone",                             last_login AS "Dernière Connexion"                         FROM membres                         WHERE groupe_id = %s                         LIMIT 30                    """                    df_admin_audit = pd.read_sql_query(query_admin_audit, engine, params=(int(choix_admin_gid),))                    if df_admin_audit.empty:                        st.warning(f"ℹ️ Le Groupe #{choix_admin_gid} ne possède pas encore de membres enregistrés.")                    else:                        df_admin_audit['Dernière Connexion'] = df_admin_audit['Dernière Connexion'].fillna(                            "Aucune session enregistrée")                        st.dataframe(                            df_admin_audit,                            use_container_width=True,                            hide_index=True,                            column_config={                                "N°": st.column_config.NumberColumn("N°", width=50),                                "Noms et Prénoms": st.column_config.TextColumn("Noms et Prénoms", width=250),                                "Sexe": st.column_config.TextColumn("Sexe", width=70),                                "Âge": st.column_config.NumberColumn("Âge", width=70),                                "Téléphone": st.column_config.TextColumn("Téléphone", width=150),                                "Dernière Connexion": st.column_config.TextColumn("🕒 Dernière Connexion", width=230)                            }                        )                # =====================================================================                # 3️⃣ ONGLET ADMIN 2 : PRESENCES                # =====================================================================                with tab_admin_presences:                    st.subheader(f"📅 Analyse des Présences Mensuelles - Groupe #{choix_admin_gid}")                    mois_actuel_admin = datetime.now().strftime("%Y-%m")                    query_mois_admin = """                        SELECT DISTINCT TO_CHAR(date_reunion::date, 'YYYY-MM') AS mois                         FROM presences p                        JOIN membres m ON p.membre_id = m.id                        WHERE m.groupe_id = %s                         ORDER BY mois DESC                    """                    list_mois_admin_df = pd.read_sql_query(query_mois_admin, engine, params=(int(choix_admin_gid),))                    périodes_admin = list_mois_admin_df['mois'].tolist() if not list_mois_admin_df.empty else []                    if mois_actuel_admin not in périodes_admin:                        périodes_admin.insert(0, mois_actuel_admin)                    période_admin_choisie = st.selectbox("📆 Choisir la période d'audit :", périodes_admin,                                                         key="perm_admin_select")                    query_dates_admin = """                        SELECT DISTINCT p.date_reunion                         FROM presences p                        JOIN membres m ON p.membre_id = m.id                        WHERE m.groupe_id = %s AND p.date_reunion::text LIKE %s                         ORDER BY p.date_reunion ASC                    """                    dates_admin_df = pd.read_sql_query(query_dates_admin, engine,                                                       params=(int(choix_admin_gid), f"{période_admin_choisie}%"))                    liste_dates_admin = dates_admin_df['date_reunion'].tolist() if not dates_admin_df.empty else []                    if not liste_dates_admin:                        st.info(                            f"ℹ️ Aucune réunion trouvée pour le Groupe #{choix_admin_gid} durant la période {période_admin_choisie}.")                    else:                        query_membres_admin = "SELECT id, (prenom || ' ' || nom) AS nom_complet FROM membres WHERE groupe_id = %s LIMIT 30"                        membres_admin_df = pd.read_sql_query(query_membres_admin, engine,                                                             params=(int(choix_admin_gid),))                        query_p_admin = """                            SELECT p.membre_id, p.date_reunion, p.status AS statut                             FROM presences p                            JOIN membres m ON p.membre_id = m.id                            WHERE m.groupe_id = %s AND p.date_reunion::text LIKE %s                        """                        presences_admin_df = pd.read_sql_query(query_p_admin, engine, params=(int(choix_admin_gid),                                                                                              f"{période_admin_choisie}%"))                        donnees_tab_admin = []                        for idx, row in membres_admin_df.iterrows():                            m_id = row['id']                            ligne = {"N°": m_id, "Noms et Prénoms": row['nom_complet']}                            total_p, total_a = 0, 0                            for date_r in liste_dates_admin:                                match = presences_admin_df[(presences_admin_df['membre_id'] == m_id) & (                                            presences_admin_df['date_reunion'] == date_r)]                                if not match.empty:                                    statut = match.iloc[0]['statut']                                    ligne[date_r] = "✅ P" if statut == "P" else "❌ A"                                    if statut == "P":                                        total_p += 1                                    else:                                        total_a += 1                                else:                                    ligne[date_r] = "➖"                                    total_a += 1                            ligne["Total Présences"] = total_p                            ligne["Total Absences"] = total_a                            donnees_tab_admin.append(ligne)                        df_admin_final_presences = pd.DataFrame(donnees_tab_admin)                        st.dataframe(df_admin_final_presences, use_container_width=True, hide_index=True)                # =====================================================================                # 4️⃣ ONGLET ADMIN 3 : FLUX CAISSE SOCIALE                # =====================================================================                with tab_adm_sociale:                    st.subheader(f"🔍 Flux Caisse Sociale - Groupe #{choix_admin_gid}")                    query_d_soc_adm = """                        SELECT DISTINCT h.date_reunion                         FROM historique_social h                        JOIN membres m ON h.membre_id = m.id                        WHERE m.groupe_id = %s                         ORDER BY h.date_reunion ASC                    """                    cur_soc = db_conn.cursor()                    cur_soc.execute(query_d_soc_adm, (int(choix_admin_gid),))                    dates_soc_adm = [r[0] for r in cur_soc.fetchall()]                    membres_adm = pd.read_sql_query(                        "SELECT id, (prenom || ' ' || nom) AS nom_complet FROM membres WHERE groupe_id = %s LIMIT 30",                        engine, params=(int(choix_admin_gid),)                    )                    if not membres_adm.empty:                        rows_soc_adm = []                        for _, m in membres_adm.iterrows():                            ligne = {"N°": m['id'], "Noms et Prénoms": m['nom_complet']}                            tot = 0                            for d in dates_soc_adm:                                cur_soc.execute(                                    "SELECT montant FROM historique_social WHERE membre_id = %s AND date_reunion = %s",                                    (int(m['id']), d)                                )                                val = cur_soc.fetchone()                                v = val[0] if val else 0.0                                ligne[d] = v                                tot += v                            ligne["Total cotisé (Caisse Sociale)"] = tot                            rows_soc_adm.append(ligne)                        cur_soc.close()                        st.dataframe(pd.DataFrame(rows_soc_adm), use_container_width=True, hide_index=True)                    else:                        cur_soc.close()                        st.info("ℹ️ Aucun membre trouvé pour ce groupe.")                # =====================================================================                # 5️⃣ ONGLET ADMIN 4 : ÉVOLUTION ÉPARGNE                # =====================================================================                with tab_adm_epargne:                    st.subheader(f"🔍 Évolution Épargne - Groupe #{choix_admin_gid}")                    query_d_ep_adm = """                        SELECT DISTINCT h.date_reunion                         FROM historique_epargne h                        JOIN membres m ON h.membre_id = m.id                        WHERE m.groupe_id = %s                         ORDER BY h.date_reunion ASC                    """                    cur_ep = db_conn.cursor()                    cur_ep.execute(query_d_ep_adm, (int(choix_admin_gid),))                    dates_ep_adm = [r[0] for r in cur_ep.fetchall()]                    if not membres_adm.empty:                        rows_ep_adm = []                        for _, m in membres_adm.iterrows():                            ligne = {"N°": m['id'], "Noms et Prénoms": m['nom_complet']}                            cumul = 0.0                            for d in dates_ep_adm:                                cur_ep.execute(                                    "SELECT montant FROM historique_epargne WHERE membre_id = %s AND date_reunion = %s",                                    (int(m['id']), d)                                )                                val = cur_ep.fetchone()                                v = val[0] if val else 0.0                                cumul += v                                ligne[d] = f"{v:,.0f} (Cumul: {cumul:,.0f})"                            ligne["Épargne Totale"] = cumul                            rows_ep_adm.append(ligne)                        cur_ep.close()                        st.dataframe(pd.DataFrame(rows_ep_adm), use_container_width=True, hide_index=True)                    else:                        cur_ep.close()                        st.info("ℹ️ Aucun membre trouvé pour ce groupe.")                # =====================================================================                # 6️⃣ ONGLET ADMIN 5 : DÉCAISSEMENTS SOCIAUX                # =====================================================================                with tab_adm_decaissement:                    st.subheader(f"📋 Registre des Décaissements Sociaux - Groupe #{choix_admin_gid}")                    query_dec = """                        SELECT m.id AS "N°", (m.prenom || ' ' || m.nom) AS "Nom", d.objet AS "Objet",                                d.date_decaissement AS "Date de Décaissement", d.montant_decaisse AS "Montant Décaissé",                                d.montant_rembourse AS "Montant Remboursé", d.enregistre_par AS "Signature"                        FROM decaissement_social d                        JOIN membres m ON d.membre_id = m.id                        WHERE d.groupe_id = %s LIMIT 30                    """                    df_dec = pd.read_sql_query(query_dec, engine, params=(int(choix_admin_gid),))                    if df_dec.empty:                        st.info("Aucun décaissement social enregistré pour ce groupe.")                    else:                        st.dataframe(df_dec, use_container_width=True, hide_index=True)                # =====================================================================                # 7️⃣ ONGLET ADMIN 6 : AMENDES À PERCEVOIR                # =====================================================================                with tab_adm_amendes:                    st.subheader(f"📋 Registre des Amendes à Percevoir - Groupe #{choix_admin_gid}")                    query_am = """                        SELECT m.id AS "N°", (m.prenom || ' ' || m.nom) AS "Membre", a.motif AS "Motif",                                a.montant_a_payer AS "Montant à payer", a.montant_paye AS "Montant Payé",                               a.date_enregistrement AS "Date Enregistrement", a.enregistre_par AS "Enregistré Par"                        FROM amendes a                        JOIN membres m ON a.membre_id = m.id                        WHERE a.groupe_id = %s LIMIT 30                    """                    df_am = pd.read_sql_query(query_am, engine, params=(int(choix_admin_gid),))                    if df_am.empty:                        st.info("Aucune amende répertoriée pour ce groupe.")                    else:                        st.dataframe(df_am, use_container_width=True, hide_index=True)                # =====================================================================                # 8️⃣ ONGLET ADMIN 7 : JOURNAL DES PRÊTS                # =====================================================================                with tab_adm_prets:                    st.subheader(f"📋 Journal Général des Prêts - Groupe #{choix_admin_gid}")                    query_pr = """                        SELECT (m.prenom || ' ' || m.nom) AS "Nom", j.objet AS "Objet",                                j.date_decaissement AS "Date Décaiss.", j.date_echeance AS "Date Échéance",                                j.enregistre_par AS "Signature", j.montant_decaisse AS "Montant Décaissé",                                j.interet AS "Intérêt", j.total_a_payer AS "Total à payer",                                j.montant_paye AS "Montant Payé", j.solde AS "Solde",                                j.date_paiement AS "Date Paiement", j.commentaire AS "Statut"                        FROM journal_prets j                        JOIN membres m ON j.membre_id = m.id                        WHERE j.groupe_id = %s LIMIT 30                    """                    df_pr = pd.read_sql_query(query_pr, engine, params=(int(choix_admin_gid),))                    if df_pr.empty:                        st.info("Aucun prêt en cours ou enregistré dans le journal de ce groupe.")                    else:                        st.dataframe(df_pr, use_container_width=True, hide_index=True)    # --- 5.2 ESPACE PRÉSIDENT / SECRÉTAIRE ---    elif role in ["president", "secretaire"]:        gid = u['groupe_id']        if choice == "Mon Compte":            u_id = st.session_state.user['id']            u = pd.read_sql("SELECT * FROM membres WHERE id=%s", engine, params=(int(u_id),)).iloc[0]            st.title("💰 Mon Portefeuille")            gid = u.get('groupe_id')            try:                cursor = db_conn.cursor()                cursor.execute("SELECT montant_hebdo FROM groupes WHERE id=%s", (int(gid),))                row_groupe = cursor.fetchone()                cotisation_hebdo = row_groupe[0] if row_groupe and row_groupe[0] is not None else 0            except Exception as e:                cotisation_hebdo = 0                st.error(f"Erreur de récupération de la cotisation : {e}")            finally:                cursor.close()            c1, c2, c3, c4 = st.columns(4)            c1.metric("Épargne Totale", f"{(u.get('solde_epargne') or 0):,.0f} BIF")            c3.metric("Prêt à Rembourser", f"{(u.get('solde_pret') or 0):,.0f} BIF")            c4.metric("Status Présence", u.get('status_presence', 'Inconnu'))            st.subheader("🛡️ Solidarité & Prêts Sociaux")            c_soc1, c_soc2 = st.columns(2)            with c_soc1:                st.markdown(f"""                    <div style="background-color:#e1f5fe; padding:15px; border-radius:10px; border-left:5px solid #03a9f4;">                        <h4 style="margin:0; color:#01579b;">Ma Caisse Sociale</h4>                        <h2 style="margin:10px 0;">{(u.get('caisse_sociale') or 0):,.0f} BIF</h2>                        <p style="font-size:0.8em; color:#555;">Fonds d'entraide communautaire</p>                    </div>                """, unsafe_allow_html=True)            with c_soc2:                st.markdown("""                    <div style="background-color:#f1f8e9; padding:15px; border-radius:10px; border-left:5px solid #8bc34a;">                        <h4 style="margin:0; color:#33691e;">Demande de Prêt Social</h4>                        <p style="margin:10px 0; font-size:0.9em;">Besoin d'un coup de pouce urgent ?</p>                    </div>                """, unsafe_allow_html=True)                with st.expander("📝 Remplir ma demande"):                    with st.form("form_pret_social"):                        montant_s = st.number_input("Somme souhaitée (BIF)", min_value=0, step=1000)                        motif_s = st.text_area("Expliquez votre besoin")                        if st.form_submit_button("Envoyer la demande"):                            if montant_s > 0:                                cur_ins_soc = db_conn.cursor()                                try:                                    cur_ins_soc.execute("""                                        INSERT INTO demandes_sociales (membre_id, montant_demande, motif, date_demande)                                         VALUES (%s, %s, %s, %s)                                    """, (int(u['id']), montant_s, motif_s, datetime.now().strftime("%Y-%m-%d")))                                    db_conn.commit()                                    st.success("✅ Demande envoyée au comité !")                                except Exception as e:                                    db_conn.rollback()                                    st.error(f"Erreur d'enregistrement : {e}")                                finally:                                    cur_ins_soc.close()                            else:                                st.error("Le montant doit être supérieur à 0.")            st.write("---")            st.subheader("📉 Suivi de mon Crédit")            c1, c2, c3 = st.columns(3)            c1.metric("Crédit en cours", f"{(u.get('credit_en_cours') or 0):,.0f} BIF")            c2.metric("Déjà remboursé", f"{(u.get('credit_rembourse') or 0):,.0f} BIF")            c3.metric(                "Reste à payer",                f"{(u.get('credit_restant') or 0):,.0f} BIF",                delta=f"-{(u.get('credit_rembourse') or 0):,.0f}",                delta_color="inverse"            )            st.write("---")            st.subheader("📎 Mes Documents (Reçus)")            doc = st.file_uploader("Associer un reçu de banque (PDF)", type="pdf")            if doc:                st.success(f"✅ Le document '{doc.name}' a été analysé et lié à votre compte.")        elif choice == "Demande de Prêt":            st.title("💸 Demande de Crédit")            solde_ep = u.get('solde_epargne') or 0            max_loan = int(solde_ep * 3)            st.warning(f"🛡️ Votre plafond de prêt (3x votre épargne) : **{max_loan:,.0f} BIF**")            with st.form("pret_form"):                montant_d = st.number_input("Montant souhaité (BIF)", min_value=0, max_value=max_loan, step=5000)                motif = st.text_area("Motif détaillé du prêt (Projet, Santé, École...)")                if st.form_submit_button("🚀 Envoyer la Demande"):                    if montant_d > 0:                        cur_ins_pret = db_conn.cursor()                        try:                            cur_ins_pret.execute("""                                INSERT INTO prets (membre_id, montant, motif, reste_a_payer, status, date_demande)                                 VALUES (%s, %s, %s, %s, 'EN ATTENTE', %s)                            """, (int(u['id']), montant_d, motif, montant_d, datetime.now().strftime("%Y-%m-%d")))                            db_conn.commit()                            st.success("✅ Votre demande a été transmise aux administrateurs.")                            st.balloons()                        except Exception as e:                            db_conn.rollback()                            st.error(f"Erreur d'enregistrement du prêt : {e}")                        finally:                            cur_ins_pret.close()                    else:                        st.error("Veuillez saisir un montant supérieur à 0.")            st.write("---")            st.subheader("📋 État de mes demandes")            mes_demandes = pd.read_sql(                "SELECT date_demande, montant, status FROM prets WHERE membre_id = %s ORDER BY id DESC",                engine, params=(int(u['id']),)            )            if not mes_demandes.empty:                def color_status(val):                    color = '#ffa500' if val == 'EN ATTENTE' else '#2ecc71' if val == 'APPROUVÉ' else '#e74c3c'                    return f'color: {color}; font-weight: bold'                st.dataframe(mes_demandes.style.map(color_status, subset=['status']), use_container_width=True)            else:                st.info("Vous n'avez aucune demande de prêt en cours.")        elif choice == "Mon Profil":            st.title("📄 Résumé de mon profil")            st.subheader(f"👤 Profil de {u['prenom']} {u['nom']}")            if 'get_live_data' in globals():                api = get_live_data()                st.info(f"📅 **{api['Date']}** à **{api['Heure']}** (Bujumbura) | {api['Bourse']} | {api['Météo']}")            st.write("---")            st.markdown(f"""                <div class="profile-card" style="background-color: #f9f9f9; padding: 20px; border-radius: 15px; border: 1px solid #ddd;">                    <h3 style="color: #2c3e50;">{u['prenom']} {u['nom']}</h3>                    <p><b>Numéro de Membre ID :</b> #00{u['id']}</p>                    <p><b>Groupe ID :</b> #00{gid}</p>                    <hr>                    <div style="display: flex; justify-content: space-between; flex-wrap: wrap;">                        <div style="flex: 1; min-width: 200px;">                            <p><b>🪪 CNI :</b> {u.get('cni', 'N/A')}</p>                            <p><b>🎂 Âge :</b> {u.get('age', 'N/A')} ans</p>                            <p><b>👫 Sexe :</b> {u.get('sexe', 'N/A')}</p>                            <p><b>📞 Téléphone :</b> {u.get('telephone', 'N/A')}</p>                        </div>                        <div style="flex: 1; min-width: 200px;">                            <p><b>📍 Colline :</b> {u.get('colline', 'N/A')}</p>                            <p><b>🏠 Quartier :</b> {u.get('quartier', 'N/A')}</p>                            <p><b>🛣️ Avenue :</b> {u.get('avenue', 'N/A')}</p>                            <p><b>🚪 Maison :</b> {u.get('maison', 'N/A')}</p>                        </div>                    </div>                    <hr>                    <p><b>🛡️ Rôle :</b> <span style="color: #3498db; font-weight: bold;">{u['role'].upper()}</span></p>                    <p><b>🕒 Dernière connexion :</b> {u.get('last_login') if u.get('last_login') else 'Première session'}</p>                </div>            """, unsafe_allow_html=True)            query_reunion = "SELECT date_reunion_derniere, date_reunion_prochaine, montant_hebdo FROM groupes WHERE id=%s"            res_reunion = pd.read_sql(query_reunion, engine, params=(int(gid),))            if not res_reunion.empty:                info_reunion = res_reunion.iloc[0]                cotisation_actuelle = info_reunion.get('montant_hebdo') or 5000                st.markdown(f"""                    <div style="background-color: #fff3e0; padding: 20px; border-radius: 15px; border-left: 5px solid #ff9800; margin-top: 20px;">                        <h3 style="color: #e65100; margin-top: 0;">📅 Calendrier & Configuration du Groupe</h3>                        <div style="display: flex; justify-content: space-between; flex-wrap: wrap; gap: 10px;">                            <div>                                <p style="margin-bottom: 5px;"><b>Dernière Réunion :</b></p>                                <p style="font-size: 1.1em; color: #5d4037;">{info_reunion['date_reunion_derniere'] or 'Non définie'}</p>                            </div>                            <div>                                <p style="margin-bottom: 5px;"><b>Prochaine Réunion :</b></p>                                <p style="font-size: 1.1em; color: #2e7d32; font-weight: bold;">{info_reunion['date_reunion_prochaine'] or 'À déterminer'}</p>                            </div>                            <div>                                <p style="margin-bottom: 5px;"><b>Cotisation Fixée :</b></p>                                <p style="font-size: 1.1em; color: #0288d1; font-weight: bold;">{cotisation_actuelle:,.0f} BIF</p>                            </div>                        </div>                    </div>                """, unsafe_allow_html=True)            else:                st.info("ℹ️ Les informations de réunion ne sont pas encore disponibles pour votre groupe.")            if 'afficher_previsions_ia' in globals():                afficher_previsions_ia(int(u['id']))            # --- AJOUT DU QR CODE DE PRÉSENCE ---            st.write("---")            st.subheader("📲 Votre Badge de Présence Numérique")            st.caption("Présentez ce QR Code à un autre membre du bureau si nécessaire pour valider votre présence.")            try:                import qrcode                import io                qr_data = f"SACCO_MEMBER_{u['id']}"                qr = qrcode.QRCode(version=1, box_size=10, border=4)                qr.add_data(qr_data)                qr.make(fit=True)                img_qr = qr.make_image(fill_color="black", back_color="white")                img_buf = io.BytesIO()                img_qr.save(img_buf, format="PNG")                st.image(img_buf.getvalue(), width=200, caption=f"Badge de {u['prenom']} {u['nom']}")            except Exception as e:                st.error(f"Impossible de générer le QR Code. Vérifiez que 'qrcode' est installé : {e}")            # --- AJOUT DES RESPONSABLES DU GROUPE ---            st.write("---")            st.subheader("👥 Responsables du Groupe")            groupe_actuel_id = gid if gid else u.get('groupe_id')            nom_president, id_president = "Non défini", "-"            nom_secretaire, id_secretaire = "Non défini", "-"            if groupe_actuel_id:                try:                    if 'get_responsables_groupe' in globals():                        resp = get_responsables_groupe(groupe_actuel_id)                        if resp:                            if 'PRESIDENT' in resp and resp['PRESIDENT'][0] not in ["Non défini", None]:                                nom_president = resp['PRESIDENT'][0]                                id_president = resp['PRESIDENT'][1]                            if 'SECRETAIRE' in resp and resp['SECRETAIRE'][0] not in ["Non défini", None]:                                nom_secretaire = resp['SECRETAIRE'][0]                                id_secretaire = resp['SECRETAIRE'][1]                    db_cursor = db_conn.cursor()                    if nom_president == "Non défini":                        db_cursor.execute("""                            SELECT id, prenom, nom FROM membres                             WHERE groupe_id = %s AND (UPPER(role) = 'PRESIDENT' OR UPPER(role) LIKE '%%PRÉSI%%') LIMIT 1                        """, (groupe_actuel_id,))                        row_p = db_cursor.fetchone()                        if row_p:                            id_president, nom_president = row_p[0], f"{row_p[1]} {row_p[2]}"                    if nom_secretaire == "Non défini":                        db_cursor.execute("""                            SELECT id, prenom, nom FROM membres                             WHERE groupe_id = %s AND (UPPER(role) = 'SECRETAIRE' OR UPPER(role) LIKE '%%SECRÉ%%') LIMIT 1                        """, (groupe_actuel_id,))                        row_s = db_cursor.fetchone()                        if row_s:                            id_secretaire, nom_secretaire = row_s[0], f"{row_s[1]} {row_s[2]}"                    db_cursor.close()                except Exception as e:                    pass                col1, col2 = st.columns(2)                with col1:                    st.write(f"**Président :** {nom_president}")                with col2:                    st.write(f"**Secrétaire :** {nom_secretaire}")        elif choice == "Historique":            st.title("📜 Historique d'Épargne et Caisse Sociale")            st.write("---")            tab_actuel, tab_archive = st.tabs(["📊 Actuel ", "🗄️ Archives (+ de 12 mois)"])            query_historique = """                SELECT date_reunion AS "Date",                 heure_enregistrement AS "Heure",                montant AS "Somme (BIF)"                 FROM historique_epargne                 WHERE membre_id = %s                 ORDER BY date_reunion DESC, heure_enregistrement DESC            """            try:                df_historique = pd.read_sql_query(query_historique, engine, params=(int(u['id']),))                def format_bif(x):                    try:                        return f"{float(x):,.0f} BIF"                    except:                        return x                if not df_historique.empty:                    df_historique['Date'] = pd.to_datetime(df_historique['Date'])                    limite_12_mois = pd.Timestamp.now() - pd.DateOffset(months=12)                    df_actuel = df_historique[df_historique['Date'] >= limite_12_mois].copy()                    df_archive = df_historique[df_historique['Date'] < limite_12_mois].copy()                    df_actuel['Date'] = df_actuel['Date'].dt.strftime('%Y-%m-%d')                    df_archive['Date'] = df_archive['Date'].dt.strftime('%Y-%m-%d')                    for df in [df_actuel, df_archive]:                        if not df.empty:                            df["Somme (BIF)"] = df["Somme (BIF)"].map(format_bif)                    with tab_actuel:                        if not df_actuel.empty:                            st.success(f"💡 Vous avez {len(df_actuel)} versement(s) sur les 12 derniers mois.")                            st.dataframe(df_actuel, use_container_width=True, hide_index=True)                        else:                            st.info("ℹ️ Aucun versement récent.")                    with tab_archive:                        if not df_archive.empty:                            st.info(f"🗄️ Vous avez {len(df_archive)} versement(s) archivé(s).")                            st.dataframe(df_archive, use_container_width=True, hide_index=True)                        else:                            st.info("ℹ️ Aucune archive disponible pour le moment.")                else:                    st.info("ℹ️ Aucun historique disponible pour le moment.")            except Exception as e:                st.error(f"Erreur lors du chargement de l'historique : {e}")                # --- 5.2.1 SAISIE HEBDOMADAIRE ---        elif choice == "Saisie Hebdomadaire":            # 1. Vérification de sécurité            user_data = st.session_state.get('user_data') or st.session_state.get('user', {})            gid = user_data.get('groupe_id')            if not gid:                st.error("❌ Votre session ne contient pas de 'groupe_id'. Veuillez vous reconnecter.")                st.stop()            st.header(f"📅 Réunion Hebdomadaire - Groupe #{gid}")            # 2. Récupération des infos du groupe            try:                group_data = pd.read_sql_query("SELECT * FROM groupes WHERE id=%s", engine, params=(int(gid),))                if group_data.empty:                    st.error("⚠️ Groupe introuvable dans la base de données.")                    st.stop()                taux_amende = group_data.iloc[0].get('taux_amende', 0) or 0                cotisation_base = group_data.iloc[0].get('montant_hebdo', 5000) or 5000            except Exception as e:                st.error(f"Erreur lors de la lecture du groupe : {e}")                st.stop()                # 3. Récupération des membres            members = pd.read_sql_query(            "SELECT id, prenom, nom FROM membres WHERE groupe_id=%s AND is_active=1",            engine, params=(int(gid),)            )            if members.empty:                st.info("ℹ️ Aucun membre actif trouvé dans ce groupe.")            date_reunion_saisie = st.date_input("Date de la réunion", datetime.today().date())            # 4. Formulaire            with st.form("feuille_saisie_hebdo"):                saisies_membres = []                for i, row in members.iterrows():                    with st.expander(f"👤 {row['prenom']} {row['nom']}"):                        c1, c2, c3 = st.columns(3)                        pres = c1.radio("Présence", ["P", "A"], key=f"p_{row['id']}")                        ep = c2.number_input("Épargne (BIF)", min_value=0, step=1000, value=int(cotisation_base),                                             key=f"m_{row['id']}")                        soc = c3.number_input("Caisse Sociale (BIF)", min_value=0, step=500, value=500,                                                  key=f"cs_{row['id']}")                        am = c3.checkbox("Amende", key=f"am_{row['id']}")                        saisies_membres.append({                            'id': row['id'],                            'epargne': ep,                            'social': soc,                            'presence': pres,                            'amende': am                        })                submit_btn = st.form_submit_button("💾 Enregistrer")                if submit_btn:                    cursor = db_conn.cursor()                    try:                        nom_responsable = f"{user_data.get('prenom', 'Admin')} {user_data.get('nom', '')}".strip()                        heure = datetime.now().strftime("%H:%M:%S")                        for am in saisies_membres:                            amende_appliquee = taux_amende if am['amende'] else 0                            final_ep = max(0.0, float(am['epargne'] - amende_appliquee))                            final_soc = float(am['social'])                            cursor.execute(                                "UPDATE membres SET solde_epargne = solde_epargne + %s, caisse_sociale = caisse_sociale + %s WHERE id = %s",                                (final_ep, final_soc, int(am['id']))                            )                            cursor.execute(                                """INSERT INTO historique_epargne                                    (membre_id, groupe_id, date_reunion, heure_enregistrement, epargne, caisse_sociale, enregistre_par)                                    VALUES (%s, %s, %s, %s, %s, %s, %s)""",                                (int(am['id']), int(gid), str(date_reunion_saisie), heure, final_ep, final_soc,                                 nom_responsable)                            )                            db_conn.commit()                        st.success("✅ Enregistré avec succès !")                    except Exception as e:                        db_conn.rollback()                        st.error(f"❌ Erreur SQL : {e}")                    finally:                        cursor.close()                # 5. MISE À JOUR DU CALENDRIER            st.write("---")            st.subheader("🗓️ Calendrier des réunions")            col1, col2 = st.columns(2)            derniere = col1.date_input("Date de la réunion d'aujourd'hui", key="derniere_reun")            prochaine = col2.date_input("Date de la prochaine réunion", key="prochaine_reun")            if st.button("Mettre à jour le calendrier du groupe"):                cur = db_conn.cursor()                try:                    cur.execute("""                                                    UPDATE groupes                             SET date_reunion_derniere = %s,                                 date_reunion_prochaine = %s                             WHERE id = %s                        """, (str(derniere), str(prochaine), int(gid)))                    db_conn.commit()                    st.success("✅ Calendrier mis à jour !")                    st.rerun()                except Exception as e:                    db_conn.rollback()                    st.error(f"Erreur lors de la mise à jour : {e}")                finally:                    cur.close()            # --- 5.2.2 TABLEAU DU GROUPE ---        elif choice == "Tableau du Groupe":            st.header(f"📊 État des Membres - Groupe #{gid}")            query = """                    SELECT nom, prenom, solde_epargne, caisse_sociale, status_presence, is_active                         FROM membres                         WHERE groupe_id = %s                    """            df = pd.read_sql(query, engine, params=(int(gid),))            if not df.empty:                df.columns = ["Nom", "Prénom", "Épargne Totale", "Caisse Sociale", "Présence", "Actif"]                st.dataframe(df, use_container_width=True)                c1, c2 = st.columns(2)                tot_epargne = df['Épargne Totale'].fillna(0).sum()                c1.metric("Épargne Totale du Groupe", f"{tot_epargne:,.0f} BIF")                c2.metric("Membres Actifs", df[df['Actif'] == 1].shape[0])            else:                st.warning("⚠️ Aucune donnée n'est disponible pour ce groupe.")        # --- 5.2.3 GESTION DES PRÊTS ---        elif choice == "Gestion des Prêts":            st.header("🏦 Validation des demandes de prêts")            # 1. Vérification et structure de la table 'prets'            try:                schema = pd.read_sql("""                            SELECT column_name                             FROM information_schema.columns                             WHERE table_name = 'prets'                        """, engine)                colonnes = schema["column_name"].tolist()                cursor = db_conn.cursor()                if "status" not in colonnes:                    cursor.execute("ALTER TABLE prets ADD COLUMN status TEXT DEFAULT 'EN ATTENTE'")                    db_conn.commit()                if "groupe_id" not in colonnes:                    cursor.execute("ALTER TABLE prets ADD COLUMN groupe_id INTEGER")                    db_conn.commit()                cursor.close()            except Exception as e:                st.error(f"Erreur de vérification de la structure base de données : {e}")            # 2. Récupération des demandes en attente            try:                query = """                            SELECT * FROM prets                             WHERE UPPER(status) = 'EN ATTENTE'                             AND (groupe_id = %s OR groupe_id IS NULL)                        """                demandes = pd.read_sql(query, engine, params=(int(gid),))            except Exception as e:                st.error(f"Erreur SQL : {e}")                st.stop()            # 3. Affichage des demandes            if demandes.empty:                st.success("✅ Aucune demande de prêt en attente.")            else:                for i, pret in demandes.iterrows():                    with st.expander(f"📄 Demande n°{pret['id']} - Membre ID: {pret['membre_id']}"):                        st.write(f"💰 Montant : {pret['montant']:,.0f} BIF")                        duree = pret.get('duree_mois', pret.get('duree', 'Non spécifiée'))                        st.write(f"📅 Durée : {duree} mois")                        if 'date_demande' in pret:                            st.write(f"🗓️ Date : {pret['date_demande']}")                        col1, col2 = st.columns(2)                        if col1.button(f"✔️ Accepter ({pret['id']})", key=f"acc_{pret['id']}"):                            cur = db_conn.cursor()                            cur.execute("UPDATE prets SET status = 'ACCEPTÉ' WHERE id = %s", (int(pret['id']),))                            db_conn.commit()                            cur.close()                            st.success(f"✅ Prêt {pret['id']} accepté.")                            st.rerun()                        if col2.button(f"❌ Refuser ({pret['id']})", key=f"ref_{pret['id']}"):                            cur = db_conn.cursor()                            cur.execute("UPDATE prets SET status = 'REFUSÉ' WHERE id = %s", (int(pret['id']),))                            db_conn.commit()                            cur.close()                            st.warning(f"❌ Prêt {pret['id']} refusé.")                            st.rerun()        # --- 5.2.4 SCANNER PRÉSENCES ---        elif choice == "Scanner Présences":            st.header("📸 Émargement par Scanner QR Code")            st.info("💡 Autorisez l'accès à votre caméra, puis présentez le code QR du membre devant l'objectif.")            current_gid = gid            group_info = pd.read_sql("SELECT taux_amende, montant_hebdo FROM groupes WHERE id=%s", engine,                                     params=(int(current_gid),))            if not group_info.empty:                taux_amende = group_info.iloc[0]['taux_amende']                montant_hebdo = group_info.iloc[0]['montant_hebdo']            else:                st.error("⚠️ Impossible de récupérer les configurations de votre groupe.")                st.stop()            img_file = st.camera_input("Scanner le Badge", key="scanner_camera_responsable")            if img_file is not None:                try:                    import cv2                    import numpy as np                    file_bytes = np.asarray(bytearray(img_file.read()), dtype=np.uint8)                    opencv_img = cv2.imdecode(file_bytes, 1)                    detector = cv2.QRCodeDetector()                    data, bbox, straight_qrcode = detector.detectAndDecode(opencv_img)                    if data and data.startswith("SACCO_MEMBER_"):                        scanned_member_id = int(data.replace("SACCO_MEMBER_", ""))                        check_membre = pd.read_sql(                            "SELECT id, nom, prenom, groupe_id, is_active FROM membres WHERE id = %s",                            engine,                            params=(scanned_member_id,)                        )                        if check_membre.empty:                            st.error("❌ Code QR invalide : Ce membre n'existe pas dans le système.")                        else:                            m_data = check_membre.iloc[0]                            if m_data['is_active'] == 0:                                st.error(                                    f"🚫 Action impossible : Le compte de {m_data['prenom']} {m_data['nom']} est archivé ou bloqué.")                            elif m_data['groupe_id'] != current_gid:                                st.error(                                    f"⚠️ Alerte sécurité : Ce membre appartient au Groupe #{m_data['groupe_id']} et non à votre groupe.")                            else:                                st.success(                                    f"🎉 Badge détecté avec succès ! Membre : **{m_data['nom']} {m_data['prenom']}**")                                st.write(                                    f"⚙️ **Écritures automatiques prévues :** Présence = 'P', Épargne = +{montant_hebdo} BIF")                                if st.button(f"💾 Confirmer l'Émargement de {m_data['prenom']}",                                             key=f"btn_qr_conf_{scanned_member_id}"):                                    cur = db_conn.cursor()                                    cur.execute("""                                                UPDATE membres SET                                                 solde_epargne = solde_epargne + %s,                                                 status_presence = 'P'                                                 WHERE id = %s                                            """, (montant_hebdo, scanned_member_id))                                    cur.execute(                                        "INSERT INTO historique_social (membre_id, montant, date_reunion) VALUES (%s, %s, %s)",                                        (scanned_member_id, 0, datetime.now().strftime('%Y-%m-%d'))                                    )                                    db_conn.commit()                                    cur.close()                                    user_nom = user_data.get('nom', 'Responsable')                                    if 'log_audit' in globals():                                        log_audit(user_nom, "EMARGEMENT_QR",                                                  f"Présence QR validée pour le membre ID {scanned_member_id}")                                    st.balloons()                                    st.success(                                        f"✅ Présence de {m_data['prenom']} {m_data['nom']} enregistrée avec succès !")                                    st.rerun()                    else:                        st.warning(                            "🔍 Aucun QR Code de la Sacco détecté. Ajustez la luminosité ou la distance de votre badge.")                except Exception as e:                    st.error(f"❌ Erreur lors du traitement du QR Code : {e}")        # --- 5.2.5 AUDIT DU GROUPE ---        elif choice == "Audit de Mon groupe":            st.header("📊 Centre d'Audit du Groupe")            def check_and_update_schema(conn):                cur = conn.cursor()                try:                    cols = {'caisse_sociale': 'NUMERIC DEFAULT 0', 'epargne': 'NUMERIC DEFAULT 0'}                    for col, definition in cols.items():                        cur.execute(                            "SELECT column_name FROM information_schema.columns WHERE table_name='historique_epargne' AND column_name=%s",                            (col,)                        )                        if not cur.fetchone():                            cur.execute(f"ALTER TABLE historique_epargne ADD COLUMN {col} {definition}")                    conn.commit()                except Exception as e:                    conn.rollback()                    st.error(f"Erreur vérification schéma : {e}")                finally:                    cur.close()            check_and_update_schema(db_conn)            tab_membres, tab_presences, tab_sociale, tab_epargne = st.tabs([                "👥 Liste", "📅 Présences", "💰 Caisse Sociale", "🐷 Épargne & Cumuls"            ])            query_m = "SELECT id, (prenom || ' ' || nom) AS nom_complet FROM membres WHERE groupe_id = %s AND is_active = 1"            membres = pd.read_sql_query(query_m, engine, params=(int(gid),))            # --- ONGLET 1 : LISTE ---            with tab_membres:                st.subheader("📋 Liste des membres avec Présences")                cur = db_conn.cursor()                cur.execute(                    "SELECT DISTINCT date_reunion FROM presences WHERE groupe_id = %s ORDER BY date_reunion ASC",                    (int(gid),)                )                dates_reunions = [r[0] for r in cur.fetchall()]                if not dates_reunions:                    st.warning("⚠️ Aucune réunion trouvée dans la table 'presences'.")                query_m_list = 'SELECT id AS "N°", (prenom || \' \' || nom) AS "Noms", sexe AS "Sexe", age AS "Âge", telephone AS "Téléphone" FROM membres WHERE groupe_id = %s'                df_membres = pd.read_sql_query(query_m_list, engine, params=(int(gid),))                if dates_reunions:                    for date_r in dates_reunions:                        date_str = str(date_r)                        df_membres[date_str] = "-"                        for index, row in df_membres.iterrows():                            cur.execute(                                "SELECT statut FROM presences WHERE membre_id = %s AND date_reunion = %s",                                (row['N°'], date_r)                            )                            res = cur.fetchone()                            if res:                                df_membres.at[index, date_str] = res[0]                cur.close()                st.dataframe(df_membres, use_container_width=True, hide_index=True)            # --- ONGLET 2 : PRÉSENCES ---            with tab_presences:                st.subheader("📅 Registre Mensuel des Présences")                cur = db_conn.cursor()                cur.execute(                    "SELECT DISTINCT date_reunion FROM presences WHERE groupe_id = %s ORDER BY date_reunion ASC",                    (int(gid),)                )                dates_pres = [r[0] for r in cur.fetchall()]                if not dates_pres:                    st.info("Aucune donnée de présence.")                else:                    rows = []                    totaux_presences = {str(d): 0 for d in dates_pres}                    for _, m in membres.iterrows():                        row = {"Noms": m['nom_complet']}                        for d in dates_pres:                            cur.execute(                                "SELECT statut FROM presences WHERE membre_id = %s AND date_reunion = %s",                                (m['id'], d)                            )                            res = cur.fetchone()                            statut = res[0] if res else "-"                            row[str(d)] = statut                            if statut in ['P', 'Présent', 'Present']:                                totaux_presences[str(d)] += 1                        rows.append(row)                    df_pres = pd.DataFrame(rows)                    ligne_total = {"Noms": "TOTAL PRÉSENTS"}                    ligne_total.update(totaux_presences)                    df_final = pd.concat([df_pres, pd.DataFrame([ligne_total])], ignore_index=True)                    st.dataframe(df_final, use_container_width=True, hide_index=True)                    st.write("---")                    st.caption(                        "✅ **Audit rapide** : Les totaux en bas de colonne permettent de vérifier le quorum à chaque séance.")                cur.close()            # --- ONGLET 3 : CAISSE SOCIALE ---            with tab_sociale:                st.subheader("💰 Registre Caisse Sociale")                cur = db_conn.cursor()                cur.execute(                    "SELECT DISTINCT date_reunion FROM historique_epargne WHERE groupe_id = %s ORDER BY date_reunion ASC",                    (int(gid),)                )                dates_soc = [r[0] for r in cur.fetchall()]                rows = []                for _, m in membres.iterrows():                    row = {"Noms": m['nom_complet']}                    tot = 0.0                    for d in dates_soc:                        cur.execute(                            "SELECT caisse_sociale FROM historique_epargne WHERE membre_id = %s AND date_reunion = %s",                            (m['id'], d)                        )                        res = cur.fetchone()                        montant = float(res[0]) if res and res[0] is not None else 0.0                        tot += montant                        row[str(d)] = f"{montant:,.0f}"                    row["Total"] = f"{tot:,.0f} BIF"                    rows.append(row)                st.dataframe(pd.DataFrame(rows), use_container_width=True)                cur.close()            # --- ONGLET 4 : ÉPARGNE ---            with tab_epargne:                st.subheader("🐷 Registre d'Épargne")                cur = db_conn.cursor()                cur.execute(                    "SELECT DISTINCT date_reunion FROM historique_epargne WHERE groupe_id = %s ORDER BY date_reunion ASC",                    (int(gid),)                )                dates_ep = [r[0] for r in cur.fetchall()]                rows = []                for _, m in membres.iterrows():                    row = {"Noms": m['nom_complet']}                    cumul = 0.0                    for d in dates_ep:                        cur.execute(                            "SELECT epargne FROM historique_epargne WHERE membre_id = %s AND date_reunion = %s",                            (m['id'], d)                        )                        res = cur.fetchone()                        montant = float(res[0]) if res and res[0] is not None else 0.0                        cumul += montant                        row[str(d)] = f"{montant:,.0f} (C: {cumul:,.0f})"                    row["Solde"] = f"{cumul:,.0f} BIF"                    rows.append(row)                st.dataframe(pd.DataFrame(rows), use_container_width=True)                cur.close()        # --- 5.2.6 PARAMÈTRES GROUPE ---        elif choice == "Paramètres Groupe":            st.subheader("⚙️ Administration & Audit Système")            # --- 1. SÉLECTION GLOBALE DU GROUPE (POUR L'ADMIN_SYS) ---            if role == "admin_sys":                st.info(                    "💡 En tant qu'Admin Système, sélectionnez un groupe ci-dessous pour auditer ou modifier ses paramètres.")                liste_groupes = pd.read_sql("SELECT id, nom_groupe FROM groupes", engine)                if not liste_groupes.empty:                    choix_groupe = st.selectbox(                        "🌍 Sélectionner le groupe à auditer / administrer :",                        options=liste_groupes['id'].tolist(),                        format_func=lambda                            x: f"Groupe #{x} - {liste_groupes[liste_groupes['id'] == x]['nom_groupe'].values[0]}"                    )                    gid = choix_groupe  # Définition globale de gid pour tout le système                else:                    st.error("⚠️ Aucun groupe existant dans la base de données du système.")                    st.stop()            else:                # Pour un administrateur local ou un membre classique                gid = u.get('groupe_id')                st.write(f"📍 *Administration de votre groupe actuel (ID: {gid})*")            # --- 2. SÉCURITÉ ANTI-PLANTAGE ---            if gid is None:                st.error("🚫 Aucun groupe assigné ou sélectionné.")                st.stop()            # --- 3. CRÉATION DES ONGLETS ---            tab1, tab2, tab3, tab4 = st.tabs([                "📅 Réunions & Cotisations",                "📊 Simulateur Financier",                "🔐 Sécurité PIN",                "🚫 Gestion des accès"            ])            # --- ONGLET 1 : RÉUNIONS & COTISATIONS ---            with tab1:                if role == "admin_sys":                    st.info(                        "💡 En tant qu'Admin Système, les modifications s'appliqueront au groupe sélectionné ci-dessus.")                st.write("### Configuration des réunions")                next_date = st.date_input("Définir la prochaine réunion", key="next_meeting")                new_hebdo = st.number_input("Montant de la cotisation hebdomadaire (BIF)", value=5000, step=500)                if st.button("Enregistrer les réglages du groupe"):                    cur = db_conn.cursor()                    try:                        cur.execute(                            "UPDATE groupes SET date_reunion_prochaine=%s, montant_hebdo=%s WHERE id=%s",                            (str(next_date), new_hebdo, int(gid))                        )                        db_conn.commit()                        # Trace d'audit système                        if 'log_audit' in globals():                            log_audit(u.get('nom', 'Admin'), "CONFIG_GROUPE",                                      f"Nouveau montant: {new_hebdo} (Groupe ID: {gid})")                        st.success("✅ Paramètres du groupe mis à jour avec succès.")                        st.rerun()                    except Exception as e:                        db_conn.rollback()                        st.error(f"❌ Erreur lors de la mise à jour : {e}")                    finally:                        cur.close()            # --- ONGLET 2 : SIMULATEUR FINANCIER ---            with tab2:                st.write("### 📈 Simulateur de Performance Financière")                group_q = pd.read_sql(                    "SELECT nom_groupe, taux_amende, date_reunion_derniere, date_reunion_prochaine FROM groupes WHERE id = %s",                    engine, params=(int(gid),)                )                if not group_q.empty:                    amende_unitaire = group_q.iloc[0]['taux_amende'] or 1000                    nom_groupe_sim = group_q.iloc[0]['nom_groupe']                    date_derniere = group_q.iloc[0]['date_reunion_derniere'] or "Non définie"                    date_prochaine = group_q.iloc[0]['date_reunion_prochaine'] or "À déterminer"                else:                    st.error("⚠️ Impossible de charger les données du groupe.")                    st.stop()                df_membres_sim = pd.read_sql(                    "SELECT id, nom, prenom, solde_epargne FROM membres WHERE groupe_id = %s AND is_active = 1",                    engine, params=(int(gid),)                )                if df_membres_sim.empty:                    st.warning(                        f"⚠️ Aucun membre actif dans le groupe '{nom_groupe_sim}' pour exécuter les simulations.")                else:                    st.markdown("#### 📅 1. Projection Globale des Intérêts (Période de 3 mois)")                    st.caption(                        f"Basé sur l'état post-réunion hebdomadaire. Dernier calendrier saisi : Du **{date_derniere}** au **{date_prochaine}**.")                    taux_annuel_sim = st.number_input("Taux d'intérêt annuel cible (%)", 0.0, 20.0, 5.0, step=0.5,                                                      key="tx_an_3m")                    taux_trimestriel = taux_annuel_sim / 4                    mult_trimestriel = 1 + (taux_trimestriel / 100)                    list_rows_interets = []                    total_interets_injectes = 0                    for _, membre in df_membres_sim.iterrows():                        solde_actuel = membre['solde_epargne'] or 0                        nouveau_solde = solde_actuel * mult_trimestriel                        interet_gagne = nouveau_solde - solde_actuel                        total_interets_injectes += interet_gagne                        list_rows_interets.append({                            "ID": f"#00{membre['id']}",                            "Nom & Prénom": f"{membre['nom']} {membre['prenom']}",                            "Épargne Actuelle (BIF)": f"{solde_actuel:,.0f}",                            "Intérêts Générés (3 mois)": f"+{interet_gagne:,.0f}",                            "Solde Estimé après 3 mois": f"{nouveau_solde:,.0f}"                        })                    st.dataframe(pd.DataFrame(list_rows_interets), use_container_width=True)                    st.success(                        f"📈 Total des intérêts théoriques injectés dans le groupe sur 3 mois : **+{total_interets_injectes:,.0f} BIF** (Taux appliqué : {taux_trimestriel:.3f}%)")                    st.write("---")                    st.markdown("#### 🚫 2. Simulateur de Retard Individuel (Période de 1 mois)")                    st.caption(                        "Permet d'évaluer l'impact financier des retards de paiement répétés pour un membre spécifique sur un mois d'activité.")                    membre_options = df_membres_sim.apply(lambda r: f"{r['nom']} {r['prenom']} (ID: #00{r['id']})",                                                          axis=1).tolist()                    membre_selectionne_str = st.selectbox("🎯 Choisir le membre en retard de paiement :",                                                          options=membre_options)                    idx_selectionne = membre_options.index(membre_selectionne_str)                    membre_cible = df_membres_sim.iloc[idx_selectionne]                    nb_retards_mois = st.number_input(                        f"Nombre de retards de paiement ce mois pour {membre_cible['prenom']}", 1, 5, 2, step=1)                    amende_totale_mois = nb_retards_mois * amende_unitaire                    solde_actuel_membre = membre_cible['solde_epargne'] or 0                    solde_apres_amende = max(0, solde_actuel_membre - amende_totale_mois)                    st.markdown(f"""                            <div style="background-color: #fff5f5; padding: 20px; border-radius: 12px; border-left: 6px solid #e74c3c; margin-top: 15px;">                                <h5 style="color: #c0392b; margin-top:0;">⚠️ Rapport de Simulation d'Amende - {membre_cible['nom']} {membre_cible['prenom']}</h5>                                <table style="width: 100%; border-collapse: collapse;">                                    <tr>                                        <td style="padding: 5px 0;"><b>Solde d'Épargne Actuel :</b></td>                                        <td style="text-align: right;">{solde_actuel_membre:,.0f} BIF</td>                                    </tr>                                    <tr>                                        <td style="padding: 5px 0; color: #c0392b;"><b>Amendes cumulées (sur 1 mois) :</b></td>                                        <td style="text-align: right; color: #c0392b; font-weight: bold;">-{amende_totale_mois:,.0f} BIF</td>                                    </tr>                                    <tr style="border-top: 1px solid #ddd;">                                        <td style="padding: 8px 0; font-size: 1.05em;"><b>Solde de sécurité projeté :</b></td>                                        <td style="text-align: right; font-size: 1.05em; font-weight: bold; color: #2c3e50;">{solde_apres_amende:,.0f} BIF</td>                                    </tr>                                </table>                                <p style="font-size: 0.85em; color: #7f8c8d; margin: 10px 0 0 0;">                                    *Note : Le taux d'amende unitaire appliqué est celui fixé par le groupe {nom_groupe_sim},                                     soit <b>{amende_unitaire:,.0f} BIF</b> par retard/absence à la réunion hebdomadaire.*                                </p>                            </div>                        """, unsafe_allow_html=True)            # --- ONGLET 3 : SÉCURITÉ PIN ---            with tab3:                st.write("### 🔐 Réinitialisation du code PIN")                if 'reset_pin_ui' in globals():                    reset_pin_ui(u)                else:                    st.error("Fonction de réinitialisation PIN non chargée.")            # --- ONGLET 4 : GESTION DES ACCÈS ---            with tab4:                st.write("### 🚫 Clôture de compte & Archivage")                st.warning("**Attention :** L'archivage d'un membre générera automatiquement un certificat de clôture.")                try:                    query_statuts = "SELECT id, (prenom || ' ' || nom) AS nom_complet, is_active, last_login FROM membres WHERE groupe_id = %s"                    df_statuts = pd.read_sql(query_statuts, engine, params=(int(gid),))                    if df_statuts.empty:                        st.info("Aucun membre trouvé pour ce groupe.")                    else:                        df_statuts['Statut'] = df_statuts['is_active'].apply(                            lambda x: "🟢 Actif" if x == 1 else "🔴 Inactif")                        st.dataframe(df_statuts[['id', 'nom_complet', 'Statut', 'last_login']],                                     use_container_width=True, hide_index=True)                        if 'interface_blocage_membre' in globals():                            interface_blocage_membre(u)                except Exception as e:                    st.error(f"Erreur lors du chargement des accès : {e}")    # --- 5.3 ESPACE MEMBRE SIMPLE ---    elif role == "membre":        if choice == "Mon Compte":            u_id = int(st.session_state.user['id'])            u = pd.read_sql("SELECT * FROM membres WHERE id=%s", engine, params=(u_id,)).iloc[0]            st.title("💰 Mon Portefeuille")            gid = u.get('groupe_id')            try:                cursor = db_conn.cursor()                cursor.execute("SELECT montant_hebdo FROM groupes WHERE id=%s", (int(gid),))                row_groupe = cursor.fetchone()                cotisation_hebdo = row_groupe[0] if row_groupe and row_groupe[0] is not None else 0                cursor.close()            except Exception as e:                cotisation_hebdo = 0                st.error(f"Erreur de récupération de la cotisation : {e}")            c1, c2, c3, c4 = st.columns(4)            c1.metric("Épargne Totale", f"{(u.get('solde_epargne') or 0):,.0f} BIF")            c2.metric("Cotisation Hebdo", f"{cotisation_hebdo:,.0f} BIF")            c3.metric("Prêt à Rembourser", f"{(u.get('solde_pret') or 0):,.0f} BIF")            c4.metric("Status Présence", u.get('status_presence', 'A'))            st.subheader("🛡️ Solidarité & Prêts Sociaux")            c_soc1, c_soc2 = st.columns(2)            with c_soc1:                st.markdown(f"""                                <div style="background-color:#e1f5fe; padding:15px; border-radius:10px; border-left:5px solid #03a9f4;">                                    <h4 style="margin:0; color:#01579b;">Ma Caisse Sociale</h4>                                    <h2 style="margin:10px 0;">{(u.get('caisse_sociale') or 0):,.0f} BIF</h2>                                    <p style="font-size:0.8em; color:#555;">Fonds d'entraide communautaire</p>                                </div>                            """, unsafe_allow_html=True)            with c_soc2:                st.markdown("""                                <div style="background-color:#f1f8e9; padding:15px; border-radius:10px; border-left:5px solid #8bc34a;">                                    <h4 style="margin:0; color:#33691e;">Demande de Prêt Social</h4>                                    <p style="margin:10px 0; font-size:0.9em;">Besoin d'un coup de pouce urgent ?</p>                                </div>                            """, unsafe_allow_html=True)                with st.expander("📝 Remplir ma demande"):                    with st.form("form_pret_social"):                        montant_s = st.number_input("Somme souhaitée (BIF)", min_value=0, step=1000)                        motif_s = st.text_area("Expliquez votre besoin")                        submit_social = st.form_submit_button("Envoyer la demande")                        if submit_social:                            if montant_s > 0:                                c_social = db_conn.cursor()                                try:                                    c_social.execute("""                                                    INSERT INTO demandes_sociales                                                     (membre_id, montant_demande, motif, date_demande)                                                     VALUES (%s, %s, %s, %s)                                                """, (int(u['id']), montant_s, motif_s,                                                      datetime.now().strftime("%Y-%m-%d")))                                    db_conn.commit()                                    st.success("✅ Demande envoyée au comité !")                                except Exception as e:                                    db_conn.rollback()                                    st.error(f"Erreur lors de l'envoi : {e}")                                finally:                                    c_social.close()                            else:                                st.error("Le montant doit être supérieur à 0.")            # --- NOUVELLE RUBRIQUE DÉDIÉE : MES DOCUMENTS (REÇUS) ---            st.write("---")            st.subheader("📎 Mes Documents (Reçus)")            doc = st.file_uploader("Associer un reçu de banque (PDF)", type="pdf")            if doc:                st.success(f"✅ Le document '{doc.name}' a été analysé et lié à votre compte.")            # --- SUIVI DE MON CRÉDIT ---            st.write("---")            st.subheader("📉 Suivi de mon Crédit")            credit_en_cours = u.get('credit_en_cours') or 0            credit_rembourse = u.get('credit_rembourse') or 0            credit_restant = u.get('credit_restant') or 0            c1, c2, c3 = st.columns(3)            c1.metric("Crédit en cours", f"{credit_en_cours:,.0f} BIF")            c2.metric("Déjà remboursé", f"{credit_rembourse:,.0f} BIF")            c3.metric("Reste à payer", f"{credit_restant:,.0f} BIF",                      delta=f"-{credit_rembourse:,.0f}", delta_color="inverse")        elif choice == "Demande de Prêt":            st.title("💸 Demande de Crédit")            epargne_actuelle = u.get('solde_epargne') or 0            max_loan = int(epargne_actuelle * 3)            st.warning(f"🛡️ Votre plafond de prêt (3x votre épargne) : **{max_loan:,.0f} BIF**")            with st.form("pret_form"):                montant_d = st.number_input("Montant souhaité (BIF)", min_value=0, max_value=max_loan, step=5000)                motif = st.text_area("Motif détaillé du prêt (Projet, Santé, École...)")                submit_pret = st.form_submit_button("🚀 Envoyer la Demande")            if submit_pret:                if montant_d > 0:                    try:                        with db_conn.cursor() as c_pret:                            c_pret.execute(                                """INSERT INTO prets                                 (membre_id, montant, motif, reste_a_payer, status, date_demande)                                 VALUES (%s,%s,%s,%s,'EN ATTENTE',%s)""",                                (int(u['id']), montant_d, motif, montant_d, datetime.now().strftime("%Y-%m-%d"))                            )                        db_conn.commit()                        st.success("✅ Votre demande a été transmise aux administrateurs.")                        st.balloons()                    except Exception as e:                        db_conn.rollback()                        st.error(f"❌ Erreur lors de la demande : {e}")                else:                    st.error("Veuillez saisir un montant supérieur à 0.")            # --- HISTORIQUE DES DEMANDES ---            st.write("---")            st.subheader("📋 État de mes demandes")            try:                mes_demandes = pd.read_sql(                    "SELECT date_demande, montant, status FROM prets WHERE membre_id = %s ORDER BY id DESC",                    engine, params=(int(u['id']),)                )                if not mes_demandes.empty:                    def color_status(val):                        color = '#ffa500' if val == 'EN ATTENTE' else '#2ecc71' if val == 'APPROUVÉ' else '#e74c3c'                        return f'color: {color}; font-weight: bold'                    st.dataframe(mes_demandes.style.map(color_status, subset=['status']),                                 use_container_width=True)                else:                    st.info("Vous n'avez aucune demande de prêt en cours.")            except Exception as e:                st.error("Impossible de charger les demandes pour le moment.")        elif choice == "Mon Profil":            st.title("📄 Résumé de mon profil")            st.subheader(f"👤 Profil de {u['prenom']} {u['nom']}")            # --- BLOC 1 : INFOS LIVE ---            if 'get_live_data' in globals():                api = get_live_data()                st.info(f"📅 **{api['Date']}** à **{api['Heure']}** (Bujumbura) | {api['Bourse']} | {api['Météo']}")            st.write("---")            gid = u.get('groupe_id', 0)            # --- BLOC 2 : AFFICHAGE DU PROFIL ---            st.markdown(f"""                <div class="profile-card" style="background-color: #f9f9f9; padding: 20px; border-radius: 15px; border: 1px solid #ddd;">                    <h3 style="color: #2c3e50;">{u['prenom']} {u['nom']}</h3>                    <p><b>Numéro de Membre ID :</b> #00{u['id']}</p>                    <p><b>Groupe ID :</b> #00{gid}</p>                    <hr>                    <div style="display: flex; justify-content: space-between; flex-wrap: wrap;">                        <div style="flex: 1; min-width: 200px;">                            <p><b>🪪 CNI :</b> {u.get('cni', 'N/A')}</p>                            <p><b>🎂 Âge :</b> {u.get('age', 'N/A')} ans</p>                            <p><b>👫 Sexe :</b> {u.get('sexe', 'N/A')}</p>                            <p><b>📞 Téléphone :</b> {u.get('telephone', 'N/A')}</p>                        </div>                        <div style="flex: 1; min-width: 200px;">                            <p><b>📍 Colline :</b> {u.get('colline', 'N/A')}</p>                            <p><b>🏠 Quartier :</b> {u.get('quartier', 'N/A')}</p>                            <p><b>🛣️ Avenue :</b> {u.get('avenue', 'N/A')}</p>                            <p><b>🚪 Maison :</b> {u.get('maison', 'N/A')}</p>                        </div>                    </div>                    <hr>                    <p><b>🛡️ Rôle :</b> <span style="color: #3498db; font-weight: bold;">{u['role'].upper()}</span></p>                    <p><b>🕒 Dernière connexion :</b> {u.get('last_login') if u.get('last_login') else 'Première session'}</p>                </div>            """, unsafe_allow_html=True)            # --- BLOC 3 : INFOS DU GROUPE ---            if gid:                try:                    query_reunion = "SELECT date_reunion_derniere, date_reunion_prochaine, montant_hebdo FROM groupes WHERE id=%s"                    res_reunion = pd.read_sql(query_reunion, engine, params=(int(gid),))                    if not res_reunion.empty:                        info_reunion = res_reunion.iloc[0]                        cotisation_actuelle = info_reunion.get('montant_hebdo', 5000)                        st.markdown(f"""                            <div style="background-color: #fff3e0; padding: 20px; border-radius: 15px; border-left: 5px solid #ff9800; margin-top: 20px;">                                <h3 style="color: #e65100; margin-top: 0;">📅 Calendrier & Configuration du Groupe</h3>                                <div style="display: flex; justify-content: space-between; flex-wrap: wrap; gap: 10px;">                                    <div>                                        <p style="margin-bottom: 5px;"><b>Dernière Réunion :</b></p>                                        <p style="font-size: 1.1em; color: #5d4037;">{info_reunion.get('date_reunion_derniere') or 'Non définie'}</p>                                    </div>                                    <div>                                        <p style="margin-bottom: 5px;"><b>Prochaine Réunion :</b></p>                                        <p style="font-size: 1.1em; color: #2e7d32; font-weight: bold;">{info_reunion.get('date_reunion_prochaine') or 'À déterminer'}</p>                                    </div>                                    <div>                                        <p style="margin-bottom: 5px;"><b>Cotisation Fixée :</b></p>                                        <p style="font-size: 1.1em; color: #0288d1; font-weight: bold;">{cotisation_actuelle:,.0f} BIF</p>                                    </div>                                </div>                            </div>                        """, unsafe_allow_html=True)                    else:                        st.info("ℹ️ Les informations de réunion ne sont pas encore disponibles pour votre groupe.")                except Exception as e:                    st.error("Erreur lors de la récupération des infos du groupe.")                if 'afficher_previsions_ia' in globals():                    afficher_previsions_ia(u.get('id'))                # --- QR CODE ---                st.write("---")                st.subheader("📲 Votre Badge de Présence Numérique")                st.caption(                    "Présentez ce QR Code à un autre membre du bureau si nécessaire pour valider votre présence.")                try:                    qr_data = f"SACCO_MEMBER_{u.get('id', 0)}"                    qr = qrcode.QRCode(version=1, box_size=10, border=4)                    qr.add_data(qr_data)                    qr.make(fit=True)                    img_qr = qr.make_image(fill_color="black", back_color="white")                    img_buf = io.BytesIO()                    img_qr.save(img_buf, format="PNG")                    st.image(img_buf.getvalue(), width=200,                             caption=f"Badge de {u.get('prenom', '')} {u.get('nom', '')}")                except Exception as e:                    st.error(f"Impossible de générer le QR Code : {e}")                # --- RESPONSABLES DU GROUPE ---                st.write("---")                st.subheader("👥 Responsables du Groupe")                nom_president, nom_secretaire = "Non défini", "Non défini"                if gid:                    try:                        with db_conn.cursor() as db_cursor:                            db_cursor.execute("""                                SELECT role, prenom, nom FROM membres                                 WHERE groupe_id = %s                                AND (UPPER(role) LIKE '%%PRÉSI%%' OR UPPER(role) LIKE '%%PRESIDENT%%'                                OR UPPER(role) LIKE '%%SECRÉ%%' OR UPPER(role) LIKE '%%SECRETAIRE%%')                                """, (int(gid),))                            responsables = db_cursor.fetchall()                            for r in responsables:                                role_resp, prenom_resp, nom_resp = r                                if "PRÉSI" in role_resp.upper() or "PRESIDENT" in role_resp.upper():                                    nom_president = f"{prenom_resp} {nom_resp}"                                elif "SECRÉ" in role_resp.upper() or "SECRETAIRE" in role_resp.upper():                                    nom_secretaire = f"{prenom_resp} {nom_resp}"                    except Exception as e:                        pass                col1, col2 = st.columns(2)                with col1:                    st.write(f"**Président :** {nom_president}")                with col2:                    st.write(f"**Secrétaire :** {nom_secretaire}")        elif choice == "Historique":            st.title("📜 Historique d'Épargne et Caisse Sociale")            st.write("---")            tab_actuel, tab_archive = st.tabs(["📊 Actuel ", "🗄️ Archives (+ de 12 mois)"])            query_historique = """                                    SELECT date_reunion AS "Date",                                            heure_enregistrement AS "Heure",                                            montant AS "Somme (BIF)"                                    FROM historique_epargne                                     WHERE membre_id = %s                                     ORDER BY date_reunion DESC, heure_enregistrement DESC                                """            try:                df_historique = pd.read_sql_query(query_historique, engine, params=(int(u.get('id', 0)),))                def format_bif(x):                    try:                        return f"{float(x):,.0f} BIF"                    except:                        return x                if not df_historique.empty:                    df_historique['Date'] = pd.to_datetime(df_historique['Date'])                    limite_12_mois = pd.Timestamp.now() - pd.DateOffset(months=12)                    df_actuel = df_historique[df_historique['Date'] >= limite_12_mois].copy()                    df_archive = df_historique[df_historique['Date'] < limite_12_mois].copy()                    df_actuel['Date'] = df_actuel['Date'].dt.strftime('%Y-%m-%d')                    df_archive['Date'] = df_archive['Date'].dt.strftime('%Y-%m-%d')                    for df in [df_actuel, df_archive]:                        if not df.empty:                            df["Somme (BIF)"] = df["Somme (BIF)"].map(format_bif)                    with tab_actuel:                        if not df_actuel.empty:                            st.success(f"💡 Vous avez {len(df_actuel)} versement(s) sur les 12 derniers mois.")                            st.dataframe(df_actuel, use_container_width=True, hide_index=True)                        else:                            st.info("ℹ️ Aucun versement récent.")                            st.dataframe(pd.DataFrame(columns=df_historique.columns), use_container_width=True,                                         hide_index=True)                    with tab_archive:                        if not df_archive.empty:                            st.info(f"🗄️ Vous avez {len(df_archive)} versement(s) archivé(s).")                            st.dataframe(df_archive, use_container_width=True, hide_index=True)                        else:                            st.info("ℹ️ Aucune archive disponible pour le moment (historique de moins de 12 mois).")                            st.dataframe(pd.DataFrame(columns=df_historique.columns), use_container_width=True,                                         hide_index=True)                else:                    colonnes = ["Date", "Heure", "Somme (BIF)"]                    df_vide = pd.DataFrame(columns=colonnes)                    with tab_actuel:                        st.info("ℹ️ Aucun historique disponible pour le moment.")                        st.dataframe(df_vide, use_container_width=True, hide_index=True)                    with tab_archive:                        st.dataframe(df_vide, use_container_width=True, hide_index=True)            except Exception as e:                st.error(f"Erreur lors du chargement de l'historique : {e}")# ==========================================# 7. PIED DE PAGE# ==========================================st.write("---")st.markdown("<p style='text-align: center; color: gray; font-size: 0.9em;'>© copyright - Sacco FinTech 2024-2026 - L'avenir pour tous au Burundi</p>", unsafe_allow_html=True)if __name__ == "__main__":    if 'logged_in' not in st.session_state:        st.session_state.logged_in = False    if not st.session_state.logged_in:        login_page()    else:        st.write("")